window.EXERCISE_LIBRARY_DATA = [{"id":"barbell-bench-press","nameZh":"杠铃卧推","nameEn":"Barbell Bench Press - Medium Grip","category":"胸部","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["平躺于卧推凳，双脚稳定踩地，眼睛位于杠铃下方。","肩胛向后下方收紧，以略宽于肩的握距稳定握住杠铃。","控制杠铃下放至中下胸，再平稳推回；全程避免耸肩和臀部离凳。"],"instructionsEn":["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.","After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"startImage":"assets/exercise-images/barbell-bench-press-0.jpg","endImage":"assets/exercise-images/barbell-bench-press-1.jpg"},{"id":"incline-dumbbell-press","nameZh":"上斜哑铃卧推","nameEn":"Incline Dumbbell Press","category":"胸部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["将靠背调至约 20-35 度，双脚踩稳，哑铃位于上胸两侧。","肩胛后收下沉，沿略向内的轨迹推起哑铃。","控制下放到舒适深度，避免肩部前移或腰部过度反弓。"],"instructionsEn":["Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.","Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.","Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells."],"startImage":"assets/exercise-images/incline-dumbbell-press-0.jpg","endImage":"assets/exercise-images/incline-dumbbell-press-1.jpg"},{"id":"push-up","nameZh":"俯卧撑","nameEn":"Pushups","category":"胸部","libraryType":"resistance","level":"初级","equipment":"徒手","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["双手略宽于肩置于地面，身体从头到脚跟保持一条直线。","屈肘下降，肘部约与躯干呈 30-60 度角。","胸部接近地面后推回起始位，保持腹部收紧，避免塌腰。"],"instructionsEn":["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."],"startImage":"assets/exercise-images/push-up-0.jpg","endImage":"assets/exercise-images/push-up-1.jpg"},{"id":"lat-pulldown","nameZh":"高位下拉","nameEn":"Close-Grip Front Lat Pulldown","category":"背部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["背阔肌"],"secondaryMuscles":["肱二头肌","中背部","肩部"],"instructionsZh":["调整座椅和腿垫，坐稳后以略宽于肩的握距抓住横杆。","先轻微下沉肩胛，再将横杆拉向锁骨附近。","控制横杆回到头顶上方，避免颈部前伸或大幅后仰借力。"],"instructionsEn":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.","After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","6. Repeat this motion for the prescribed amount of repetitions."],"startImage":"assets/exercise-images/lat-pulldown-0.jpg","endImage":"assets/exercise-images/lat-pulldown-1.jpg"},{"id":"bent-over-barbell-row","nameZh":"杠铃俯身划船","nameEn":"Bent Over Barbell Row","category":"背部","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"拉","mechanic":"复合动作","primaryMuscles":["中背部"],"secondaryMuscles":["肱二头肌","背阔肌","肩部"],"instructionsZh":["双脚与髋同宽，髋向后折叠，躯干稳定并保持背部自然中立。","握住杠铃，让杠铃自然悬于膝前。","用肘部向后带动杠铃拉向下腹部，再缓慢控制下放。"],"instructionsEn":["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.","Then inhale and slowly lower the barbell back to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/bent-over-barbell-row-0.jpg","endImage":"assets/exercise-images/bent-over-barbell-row-1.jpg"},{"id":"seated-cable-row","nameZh":"坐姿绳索划船","nameEn":"Seated Cable Rows","category":"背部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["中背部"],"secondaryMuscles":["肱二头肌","背阔肌","肩部"],"instructionsZh":["坐稳并将双脚抵住踏板，膝盖微屈，躯干保持直立。","先让肩胛后收，再将把手拉向腹部。","回放时手臂平稳伸展，避免耸肩或让躯干大幅摆动。"],"instructionsEn":["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the V-bar handles.","With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/seated-cable-row-0.jpg","endImage":"assets/exercise-images/seated-cable-row-1.jpg"},{"id":"one-arm-dumbbell-row","nameZh":"单臂哑铃划船","nameEn":"One-Arm Dumbbell Row","category":"背部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"拉","mechanic":"复合动作","primaryMuscles":["中背部"],"secondaryMuscles":["肱二头肌","背阔肌","肩部"],"instructionsZh":["一手一膝支撑在凳上，另一脚踩稳地面，脊柱保持中立。","让哑铃自然垂于肩下，肩胛不要耸起。","将手肘朝髋部方向拉动，顶端短暂停顿后控制下降。"],"instructionsEn":["Choose a flat bench and place a dumbbell on each side of it.","Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.","Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.","Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.","Lower the resistance straight down to the starting position. Breathe in as you perform this step.","Repeat the movement for the specified amount of repetitions.","Switch sides and repeat again with the other arm."],"startImage":"assets/exercise-images/one-arm-dumbbell-row-0.jpg","endImage":"assets/exercise-images/one-arm-dumbbell-row-1.jpg"},{"id":"dumbbell-shoulder-press","nameZh":"哑铃肩推","nameEn":"Dumbbell Shoulder Press","category":"肩部","libraryType":"resistance","level":"中级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["肩部"],"secondaryMuscles":["肱三头肌"],"instructionsZh":["坐姿或站姿保持躯干稳定，双手将哑铃置于肩部两侧。","收紧腹部，沿身体略前方的轨迹向上推举。","推至耳朵上方后缓慢下降，避免腰椎后仰和耸肩。"],"instructionsEn":["While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.","Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.","Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.","Now, exhale and push the dumbbells upward until they touch at the top.","Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/dumbbell-shoulder-press-0.jpg","endImage":"assets/exercise-images/dumbbell-shoulder-press-1.jpg"},{"id":"side-lateral-raise","nameZh":"哑铃侧平举","nameEn":"Side Lateral Raise","category":"肩部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":[],"instructionsZh":["站稳后双手持轻哑铃置于身体两侧，手肘微屈。","以肩部带动上臂向两侧抬起，至接近肩高即可。","缓慢回到起始位，避免用躯干摆动或耸肩带动重量。"],"instructionsEn":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.","While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbells back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/side-lateral-raise-0.jpg","endImage":"assets/exercise-images/side-lateral-raise-1.jpg"},{"id":"barbell-curl","nameZh":"杠铃弯举","nameEn":"Barbell Curl","category":"手臂","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":["前臂"],"instructionsZh":["站姿握住杠铃，上臂自然贴近躯干，手腕保持中立。","固定上臂，只通过屈肘将杠铃弯举至接近肩前。","缓慢降低杠铃并维持张力，避免后仰或摆动借力。"],"instructionsEn":["Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/barbell-curl-0.jpg","endImage":"assets/exercise-images/barbell-curl-1.jpg"},{"id":"dumbbell-hammer-curl","nameZh":"哑铃锤式弯举","nameEn":"Hammer Curls","category":"手臂","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":[],"instructionsZh":["双手中立握持哑铃，上臂保持贴近躯干。","以屈肘将哑铃向肩部抬起，掌心始终相对。","控制下降，避免耸肩或身体摇晃。"],"instructionsEn":["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.","After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/dumbbell-hammer-curl-0.jpg","endImage":"assets/exercise-images/dumbbell-hammer-curl-1.jpg"},{"id":"triceps-pushdown","nameZh":"绳索下压","nameEn":"Triceps Pushdown","category":"手臂","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"推","mechanic":"孤立动作","primaryMuscles":["肱三头肌"],"secondaryMuscles":[],"instructionsZh":["面对高位滑轮站稳，双手握住把手，手肘固定于身体两侧。","保持上臂不动，向下伸直手肘直至肱三头肌收紧。","缓慢回到起始位，避免肩部向前移动或借助躯干。"],"instructionsEn":["Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.","Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/triceps-pushdown-0.jpg","endImage":"assets/exercise-images/triceps-pushdown-1.jpg"},{"id":"barbell-squat","nameZh":"杠铃深蹲","nameEn":"Barbell Full Squat","category":"腿部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌","下背部"],"instructionsZh":["将杠铃稳定置于上背部，双脚与肩同宽，脚掌均匀受力。","髋和膝同步下屈，膝盖沿脚尖方向移动。","在无痛且躯干稳定的深度停下，再通过髋膝伸展平稳站起。"],"instructionsEn":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.","Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.","Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/barbell-squat-0.jpg","endImage":"assets/exercise-images/barbell-squat-1.jpg"},{"id":"leg-press","nameZh":"腿举","nameEn":"Leg Press","category":"腿部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌"],"instructionsZh":["坐稳后将腰背和臀部贴紧靠垫，双脚置于踏板中部。","解锁后缓慢屈膝下放，保持膝盖沿脚尖方向移动。","在骨盆不卷起的范围内推回，避免在顶端锁死膝盖。"],"instructionsEn":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],"startImage":"assets/exercise-images/leg-press-0.jpg","endImage":"assets/exercise-images/leg-press-1.jpg"},{"id":"romanian-deadlift","nameZh":"罗马尼亚硬拉","nameEn":"Romanian Deadlift","category":"腿部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"拉","mechanic":"复合动作","primaryMuscles":["腘绳肌"],"secondaryMuscles":["小腿","臀肌","下背部"],"instructionsZh":["站姿持杠铃或哑铃，膝盖微屈，重量贴近大腿。","向后推髋并保持背部自然中立，让重量沿腿部下降。","感到腘绳肌拉伸后，以臀部发力将髋带回站立位。"],"instructionsEn":["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.","Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.","Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.","Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/romanian-deadlift-0.jpg","endImage":"assets/exercise-images/romanian-deadlift-1.jpg"},{"id":"lying-leg-curls","nameZh":"俯卧腿弯举","nameEn":"Lying Leg Curls","category":"腿部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["腘绳肌"],"secondaryMuscles":[],"instructionsZh":["俯卧于器械上，使膝关节与器械转轴对齐，骨盆贴稳靠垫。","以脚跟向臀部方向卷起滚轮。","缓慢回到起始位，全程避免抬臀或甩动重量。"],"instructionsEn":["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.","Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.","As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/lying-leg-curls-0.jpg","endImage":"assets/exercise-images/lying-leg-curls-1.jpg"},{"id":"barbell-hip-thrust","nameZh":"杠铃臀推","nameEn":"Barbell Hip Thrust","category":"臀部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["臀肌"],"secondaryMuscles":["小腿","腘绳肌"],"instructionsZh":["上背靠稳凳缘，杠铃横置于髋部并垫好保护垫。","脚跟发力伸髋，顶端让躯干与大腿接近一线。","收紧臀部后缓慢下放，避免腰椎过伸。"],"instructionsEn":["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.","Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.","Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."],"startImage":"assets/exercise-images/barbell-hip-thrust-0.jpg","endImage":"assets/exercise-images/barbell-hip-thrust-1.jpg"},{"id":"cable-kickback","nameZh":"绳索后踢腿","nameEn":"One-Legged Cable Kickback","category":"臀部","libraryType":"resistance","level":"中级","equipment":"绳索器械","force":"推","mechanic":"孤立动作","primaryMuscles":["臀肌"],"secondaryMuscles":["腘绳肌"],"instructionsZh":["将脚踝绑带连接低位滑轮，扶稳器械并保持骨盆朝前。","保持躯干稳定，向后伸髋带动工作腿后踢。","在臀部收紧处短暂停顿，缓慢回到起始位，避免腰部代偿。"],"instructionsEn":["Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.","Face the weight stack from a distance of about two feet, grasping the steel frame for support.","While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly \"kick\" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.","Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement for the other side."],"startImage":"assets/exercise-images/cable-kickback-0.jpg","endImage":"assets/exercise-images/cable-kickback-1.jpg"},{"id":"cable-crunch","nameZh":"绳索卷腹","nameEn":"Cable Crunch","category":"核心","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["跪于高位滑轮前，双手将绳索固定在头部两侧。","保持髋部相对稳定，用肋骨向骨盆靠近的方式卷曲躯干。","缓慢回到起始位，不要只靠手臂将绳索拉下。"],"instructionsEn":["Kneel below a high pulley that contains a rope attachment.","Grasp cable rope attachment and lower the rope until your hands are placed next to your face.","Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.","With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.","Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/cable-crunch-0.jpg","endImage":"assets/exercise-images/cable-crunch-1.jpg"},{"id":"weighted-sit-up","nameZh":"负重卷腹","nameEn":"Weighted Crunches","category":"核心","libraryType":"resistance","level":"初级","equipment":"药球","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["仰卧屈膝，双手将杠铃片或哑铃稳定放在胸前。","从腹部发力卷起躯干，避免猛拉颈部。","缓慢下降回到起始位；腰部不适时改用绳索或器械卷腹。"],"instructionsEn":["Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.","Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position.","Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor.","At the top of the movement, flex your abdominals and hold for a brief pause.","Then inhale and slowly lower yourself back down to the starting position."],"startImage":"assets/exercise-images/weighted-sit-up-0.jpg","endImage":"assets/exercise-images/weighted-sit-up-1.jpg"},{"id":"dumbbell-bench-press","nameZh":"哑铃平板卧推","nameEn":"Dumbbell Bench Press","category":"胸部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["平躺于凳面，双脚稳踩地面，哑铃置于胸部两侧。","肩胛轻微后收下沉，沿稳定轨迹将哑铃推至胸前上方。","控制下放至上臂接近躯干平齐，避免耸肩或反弹。"],"instructionsEn":["Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.","Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions of your training program."],"startImage":"assets/exercise-images/dumbbell-bench-press-0.jpg","endImage":"assets/exercise-images/dumbbell-bench-press-1.jpg"},{"id":"decline-dumbbell-bench-press","nameZh":"下斜哑铃卧推","nameEn":"Decline Dumbbell Bench Press","category":"胸部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["固定双腿并躺稳下斜凳，哑铃从下胸两侧开始。","保持肩胛稳定，向上推举至手臂接近伸直。","缓慢下放并始终保持哑铃路径可控。"],"instructionsEn":["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","Once you are laying down, move the dumbbells in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..","Repeat the movement for the prescribed amount of repetitions of your training program."],"startImage":"assets/exercise-images/decline-dumbbell-bench-press-0.jpg","endImage":"assets/exercise-images/decline-dumbbell-bench-press-1.jpg"},{"id":"cable-crossover","nameZh":"绳索夹胸","nameEn":"Cable Crossover","category":"胸部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"推","mechanic":"孤立动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部"],"instructionsZh":["双脚前后站稳，双手握住高位滑轮把手，手肘微屈。","以胸部发力将双手沿弧线向身体前下方合拢。","顶端短暂停顿，再控制回放，不让肩部前冲。"],"instructionsEn":["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.","Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."],"startImage":"assets/exercise-images/cable-crossover-0.jpg","endImage":"assets/exercise-images/cable-crossover-1.jpg"},{"id":"chest-dips","nameZh":"双杠臂屈伸","nameEn":"Dips - Chest Version","category":"胸部","libraryType":"resistance","level":"中级","equipment":"其他","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["双手支撑双杠，肩胛下沉，身体轻微前倾。","屈肘下降至肩部舒适深度，躯干保持稳定。","用胸部和肱三头肌平稳推回，避免耸肩。"],"instructionsEn":["For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.","While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.","Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.","Repeat the movement for the prescribed amount of repetitions."],"startImage":"assets/exercise-images/chest-dips-0.jpg","endImage":"assets/exercise-images/chest-dips-1.jpg"},{"id":"incline-dumbbell-flyes","nameZh":"上斜哑铃飞鸟","nameEn":"Incline Dumbbell Flyes","category":"胸部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部"],"instructionsZh":["将凳面调至约 20-35 度，双手持哑铃于胸前上方。","保持肘部微屈，向两侧缓慢打开至胸部有拉伸感。","用胸部收缩将哑铃沿弧线带回，避免完全锁肘。"],"instructionsEn":["Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.","Extend your arms above you with a slight bend at the elbows.","Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.","As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.","As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/incline-dumbbell-flyes-0.jpg","endImage":"assets/exercise-images/incline-dumbbell-flyes-1.jpg"},{"id":"cable-chest-press","nameZh":"绳索推胸","nameEn":"Cable Chest Press","category":"胸部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["站在滑轮中间，双手握把，前后站姿稳定躯干。","从胸前将把手向前推出，同时保持肋骨不过度外翻。","缓慢回到胸侧起始位，维持绳索张力。"],"instructionsEn":["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.","After pausing at full extension, return to th starting position, keeping tension on the cables.","You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands."],"startImage":"assets/exercise-images/cable-chest-press-0.jpg","endImage":"assets/exercise-images/cable-chest-press-1.jpg"},{"id":"pullups","nameZh":"引体向上","nameEn":"Pullups","category":"背部","libraryType":"resistance","level":"初级","equipment":"徒手","force":"拉","mechanic":"复合动作","primaryMuscles":["背阔肌"],"secondaryMuscles":["肱二头肌","中背部"],"instructionsZh":["双手略宽于肩握杠，先下沉肩胛并收紧躯干。","以肘部向下向后带动身体，拉至下巴接近单杠。","控制下降至手臂伸直，避免摆动借力。"],"instructionsEn":["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"startImage":"assets/exercise-images/pullups-0.jpg","endImage":"assets/exercise-images/pullups-1.jpg"},{"id":"wide-grip-lat-pulldown","nameZh":"宽握高位下拉","nameEn":"Wide-Grip Lat Pulldown","category":"背部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["背阔肌"],"secondaryMuscles":["肱二头肌","中背部","肩部"],"instructionsZh":["坐稳并固定大腿，双手宽握横杆，胸廓自然抬起。","先下沉肩胛，再将横杆拉向上胸位置。","缓慢回放至手臂接近伸直，避免颈部前伸。"],"instructionsEn":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.","After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"startImage":"assets/exercise-images/wide-grip-lat-pulldown-0.jpg","endImage":"assets/exercise-images/wide-grip-lat-pulldown-1.jpg"},{"id":"lying-tbar-row","nameZh":"胸托 T 杠划船","nameEn":"Lying T-Bar Row","category":"背部","libraryType":"resistance","level":"中级","equipment":"固定器械","force":"拉","mechanic":"复合动作","primaryMuscles":["中背部"],"secondaryMuscles":["肱二头肌","背阔肌"],"instructionsZh":["胸部贴稳支撑垫，双手握住把手，颈部保持中立。","先让肩胛后收，再用肘部将把手拉向下胸。","顶端停顿后控制下放，避免耸肩。"],"instructionsEn":["Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.","Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.","Lift the bar off the rack and extend your arms in front of you. This will be your starting position.","As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.","After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/lying-tbar-row-0.jpg","endImage":"assets/exercise-images/lying-tbar-row-1.jpg"},{"id":"rope-straight-arm-pulldown","nameZh":"绳索直臂下拉","nameEn":"Rope Straight-Arm Pulldown","category":"背部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["背阔肌"],"secondaryMuscles":[],"instructionsZh":["面对高位滑轮站稳，双手握住绳索，手肘保持轻微弯曲。","固定肘角度，以肩关节发力将绳索拉向大腿。","缓慢回到起始位，避免躯干后仰。"],"instructionsEn":["Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.","Keeping your arms straight, extend the shoulder to pull the rope down to your thighs.","Pause at the bottom of the motion, squeezing your lats.","Return to the starting position without allowing the weight to fully rest on the stack."],"startImage":"assets/exercise-images/rope-straight-arm-pulldown-0.jpg","endImage":"assets/exercise-images/rope-straight-arm-pulldown-1.jpg"},{"id":"back-extension","nameZh":"罗马椅挺身","nameEn":"Hyperextensions (Back Extensions)","category":"背部","libraryType":"resistance","level":"初级","equipment":"其他","force":"拉","mechanic":"孤立动作","primaryMuscles":["下背部"],"secondaryMuscles":["臀肌","腘绳肌"],"instructionsZh":["将骨盆稳放在罗马椅垫上，双脚固定，脊柱保持自然中立。","从髋部前屈下降到舒适范围，不圆背下坠。","收紧臀部和背部回到身体成一直线，避免过度后伸。"],"instructionsEn":["Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.","Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.","With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.","Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.","Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/back-extension-0.jpg","endImage":"assets/exercise-images/back-extension-1.jpg"},{"id":"arnold-dumbbell-press","nameZh":"阿诺德推举","nameEn":"Arnold Dumbbell Press","category":"肩部","libraryType":"resistance","level":"中级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["肩部"],"secondaryMuscles":["肱三头肌"],"instructionsZh":["坐姿持哑铃于肩前，掌心朝向身体，核心收紧。","推举时同步向外旋转手腕，至哑铃位于头顶上方。","反向旋转并缓慢下降，避免腰椎后仰。"],"instructionsEn":["Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.","Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.","Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.","After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/arnold-dumbbell-press-0.jpg","endImage":"assets/exercise-images/arnold-dumbbell-press-1.jpg"},{"id":"barbell-shoulder-press","nameZh":"杠铃肩推","nameEn":"Barbell Shoulder Press","category":"肩部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["肩部"],"secondaryMuscles":["胸部","肱三头肌"],"instructionsZh":["站姿或坐姿将杠铃置于锁骨上方，双手略宽于肩。","收紧腹部，将杠铃沿面部前方垂直推向头顶。","控制下降回锁骨附近，避免耸肩和后仰。"],"instructionsEn":["Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).","Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the shoulders slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/barbell-shoulder-press-0.jpg","endImage":"assets/exercise-images/barbell-shoulder-press-1.jpg"},{"id":"front-dumbbell-raise","nameZh":"哑铃前平举","nameEn":"Front Dumbbell Raise","category":"肩部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":[],"instructionsZh":["站稳后双手持轻哑铃置于大腿前，手肘微屈。","以肩前束带动哑铃向前抬至接近肩高。","缓慢下降，避免借助躯干摆动。"],"instructionsEn":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.","Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.","Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm."],"startImage":"assets/exercise-images/front-dumbbell-raise-0.jpg","endImage":"assets/exercise-images/front-dumbbell-raise-1.jpg"},{"id":"cable-rear-delt-fly","nameZh":"绳索反向飞鸟","nameEn":"Cable Rear Delt Fly","category":"肩部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":[],"instructionsZh":["站在双滑轮之间，交叉握住对侧把手，手肘微屈。","保持躯干稳定，向两侧打开手臂并带动肩胛轻微后收。","控制回到起始位，避免耸肩。"],"instructionsEn":["Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.","Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.","Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.","Pause at the end of the motion before returning the handles to the start position."],"startImage":"assets/exercise-images/cable-rear-delt-fly-0.jpg","endImage":"assets/exercise-images/cable-rear-delt-fly-1.jpg"},{"id":"face-pull","nameZh":"绳索面拉","nameEn":"Face Pull","category":"肩部","libraryType":"resistance","level":"中级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["肩部"],"secondaryMuscles":["中背部"],"instructionsZh":["将绳索设在面部高度，双手握绳并向后退一步站稳。","向面部方向拉绳，同时让肘部向外打开。","顶端轻收肩胛后控制回放，避免腰部借力。"],"instructionsEn":["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."],"startImage":"assets/exercise-images/face-pull-0.jpg","endImage":"assets/exercise-images/face-pull-1.jpg"},{"id":"upright-barbell-row","nameZh":"杠铃直立划船","nameEn":"Upright Barbell Row","category":"肩部","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"拉","mechanic":"复合动作","primaryMuscles":["肩部"],"secondaryMuscles":["斜方肌"],"instructionsZh":["窄握杠铃置于大腿前，肩胛自然下沉。","沿身体前侧向上拉起杠铃，肘部带动并保持略高于手腕。","在肩部舒适高度停下，再平稳下放。"],"instructionsEn":["Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.","Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.","Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/upright-barbell-row-0.jpg","endImage":"assets/exercise-images/upright-barbell-row-1.jpg"},{"id":"preacher-curl","nameZh":"牧师凳弯举","nameEn":"Preacher Curl","category":"手臂","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":[],"instructionsZh":["上臂贴稳牧师凳垫，双手握住曲杆或杠铃。","固定上臂，屈肘将重量弯举至肱二头肌收紧。","缓慢下降，底部保留微屈避免关节冲击。"],"instructionsEn":["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.","With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.","As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/preacher-curl-0.jpg","endImage":"assets/exercise-images/preacher-curl-1.jpg"},{"id":"concentration-curl","nameZh":"哑铃集中弯举","nameEn":"Concentration Curls","category":"手臂","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":["前臂"],"instructionsZh":["坐姿分腿，工作侧上臂抵住同侧大腿内侧。","只通过屈肘将哑铃弯举向肩部。","顶端收紧后缓慢下降，躯干保持稳定。"],"instructionsEn":["Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.","Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.","Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm."],"startImage":"assets/exercise-images/concentration-curl-0.jpg","endImage":"assets/exercise-images/concentration-curl-1.jpg"},{"id":"cable-overhead-triceps-extension","nameZh":"绳索过顶臂屈伸","nameEn":"Cable Rope Overhead Triceps Extension","category":"手臂","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"推","mechanic":"孤立动作","primaryMuscles":["肱三头肌"],"secondaryMuscles":[],"instructionsZh":["背对高位滑轮站稳，双手握绳置于头后，上臂靠近耳侧。","固定上臂，向前上方伸肘直至肱三头肌收紧。","缓慢屈肘回到头后，避免腰部后仰。"],"instructionsEn":["Attach a rope to the bottom pulley of the pulley machine.","Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.","Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/cable-overhead-triceps-extension-0.jpg","endImage":"assets/exercise-images/cable-overhead-triceps-extension-1.jpg"},{"id":"lying-triceps-press","nameZh":"仰卧臂屈伸","nameEn":"Lying Triceps Press","category":"手臂","libraryType":"resistance","level":"中级","equipment":"曲杆","force":"推","mechanic":"孤立动作","primaryMuscles":["肱三头肌"],"secondaryMuscles":[],"instructionsZh":["平躺于凳上，将曲杆举于胸前上方，上臂保持垂直。","只屈肘让曲杆缓慢下降至额头上方或头后舒适位置。","伸肘推回起始位，避免肩部大幅前后移动。"],"instructionsEn":["Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.","Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.","As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.","At that point, use the triceps to bring the weight back up to the starting position as you breathe out.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/lying-triceps-press-0.jpg","endImage":"assets/exercise-images/lying-triceps-press-1.jpg"},{"id":"bench-dips","nameZh":"凳上臂屈伸","nameEn":"Bench Dips","category":"手臂","libraryType":"resistance","level":"初级","equipment":"徒手","force":"推","mechanic":"复合动作","primaryMuscles":["肱三头肌"],"secondaryMuscles":["胸部","肩部"],"instructionsZh":["双手撑于凳缘，手指朝前，双脚向前伸出并保持臀部靠近凳面。","屈肘下降至肩部舒适范围，保持胸廓自然抬起。","伸肘推回，避免肩部耸起或过度前移。"],"instructionsEn":["For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.","Using your triceps to bring your torso up again, lift yourself back to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/bench-dips-0.jpg","endImage":"assets/exercise-images/bench-dips-1.jpg"},{"id":"cable-hammer-curl","nameZh":"绳索锤式弯举","nameEn":"Cable Hammer Curls - Rope Attachment","category":"手臂","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":[],"instructionsZh":["面对低位滑轮站稳，双手中立握住绳索两端。","固定上臂，以屈肘将绳索拉向肩前。","缓慢下降，避免身体后仰或甩动。"],"instructionsEn":["Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.","Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.","Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.","Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.","After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/cable-hammer-curl-0.jpg","endImage":"assets/exercise-images/cable-hammer-curl-1.jpg"},{"id":"dumbbell-lunges","nameZh":"哑铃箭步蹲","nameEn":"Dumbbell Lunges","category":"腿部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌"],"instructionsZh":["双手持哑铃站稳，向前迈出一大步，保持躯干直立。","前后膝同时下屈，前膝与脚尖方向一致。","通过前脚全掌发力回到站姿，换边完成。"],"instructionsEn":["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."],"startImage":"assets/exercise-images/dumbbell-lunges-0.jpg","endImage":"assets/exercise-images/dumbbell-lunges-1.jpg"},{"id":"barbell-lunge","nameZh":"杠铃箭步蹲","nameEn":"Barbell Lunge","category":"腿部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌"],"instructionsZh":["将杠铃稳放在上背部，站稳后向前迈步。","控制身体下沉，保持骨盆稳定和前膝对线。","以前脚发力站起并回到起始位。"],"instructionsEn":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."],"startImage":"assets/exercise-images/barbell-lunge-0.jpg","endImage":"assets/exercise-images/barbell-lunge-1.jpg"},{"id":"leg-extensions","nameZh":"腿屈伸","nameEn":"Leg Extensions","category":"腿部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"孤立动作","primaryMuscles":["股四头肌"],"secondaryMuscles":[],"instructionsZh":["调整靠垫和转轴，使膝关节与器械轴心对齐。","收紧股四头肌，平稳伸膝将小腿抬起。","顶端短暂停顿后缓慢下降，不甩重量。"],"instructionsEn":["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.","Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.","Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.","Repeat for the recommended amount of times."],"startImage":"assets/exercise-images/leg-extensions-0.jpg","endImage":"assets/exercise-images/leg-extensions-1.jpg"},{"id":"seated-leg-curl","nameZh":"坐姿腿弯举","nameEn":"Seated Leg Curl","category":"腿部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["腘绳肌"],"secondaryMuscles":[],"instructionsZh":["调整座椅和压腿垫，臀部和背部贴稳靠垫。","以脚跟向下后方卷动滚轮，完成屈膝。","缓慢回放，保持腘绳肌张力。"],"instructionsEn":["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.","Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.","As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/seated-leg-curl-0.jpg","endImage":"assets/exercise-images/seated-leg-curl-1.jpg"},{"id":"standing-calf-raises","nameZh":"站姿提踵","nameEn":"Standing Calf Raises","category":"腿部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"孤立动作","primaryMuscles":["小腿"],"secondaryMuscles":[],"instructionsZh":["前脚掌踩稳踏板，肩部置于垫下，膝盖保持轻微放松。","通过踝关节跖屈抬起脚跟至最高点。","顶端停顿后缓慢下降至小腿拉伸位置。"],"instructionsEn":["Adjust the padded lever of the calf raise machine to fit your height.","Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/standing-calf-raises-0.jpg","endImage":"assets/exercise-images/standing-calf-raises-1.jpg"},{"id":"dumbbell-step-ups","nameZh":"哑铃登台阶","nameEn":"Dumbbell Step Ups","category":"腿部","libraryType":"resistance","level":"中级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌"],"instructionsZh":["双手持哑铃，选择稳定且高度合适的台阶。","一脚全掌踩上台阶，通过踩台腿发力站直。","控制下台并换边，避免借助后脚猛蹬。"],"instructionsEn":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.","Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.","Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg."],"startImage":"assets/exercise-images/dumbbell-step-ups-0.jpg","endImage":"assets/exercise-images/dumbbell-step-ups-1.jpg"},{"id":"hack-squat","nameZh":"哈克深蹲","nameEn":"Hack Squat","category":"腿部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌"],"instructionsZh":["背部和肩部贴稳器械，双脚置于踏板合适位置。","解除安全锁后屈膝下放，保持膝盖沿脚尖方向移动。","在骨盆稳定的深度后平稳蹬回，避免锁死膝盖。"],"instructionsEn":["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).","Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/hack-squat-0.jpg","endImage":"assets/exercise-images/hack-squat-1.jpg"},{"id":"single-leg-glute-bridge","nameZh":"单腿臀桥","nameEn":"Single Leg Glute Bridge","category":"臀部","libraryType":"resistance","level":"初级","equipment":"徒手","force":"推","mechanic":"孤立动作","primaryMuscles":["臀肌"],"secondaryMuscles":["腘绳肌"],"instructionsZh":["仰卧屈一侧膝，另一腿抬起伸直，骨盆保持水平。","通过支撑脚跟和臀部发力抬髋。","顶端收紧臀部后缓慢下放，避免腰椎过伸。"],"instructionsEn":["Lay on the floor with your feet flat and knees bent.","Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.","Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.","Extend as far as possible, pause and then return to the starting position."],"startImage":"assets/exercise-images/single-leg-glute-bridge-0.jpg","endImage":"assets/exercise-images/single-leg-glute-bridge-1.jpg"},{"id":"glute-ham-raise","nameZh":"臀腿挺身","nameEn":"Glute Ham Raise","category":"臀部","libraryType":"resistance","level":"中级","equipment":"固定器械","force":"拉","mechanic":"复合动作","primaryMuscles":["腘绳肌"],"secondaryMuscles":["小腿","臀肌"],"instructionsZh":["将脚踝固定于器械，身体从肩到膝保持一条直线。","控制身体前倾，保持髋部不过度屈曲。","收紧臀腿和腘绳肌将身体拉回起始位。"],"instructionsEn":["Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.","Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.","Return to the starting position, keeping your descent under control."],"startImage":"assets/exercise-images/glute-ham-raise-0.jpg","endImage":"assets/exercise-images/glute-ham-raise-1.jpg"},{"id":"sumo-deadlift","nameZh":"相扑硬拉","nameEn":"Sumo Deadlift","category":"臀部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"拉","mechanic":"复合动作","primaryMuscles":["腘绳肌"],"secondaryMuscles":["髋内收肌群","前臂","臀肌","下背部","中背部","股四头肌","斜方肌"],"instructionsZh":["双脚宽站，脚尖外开，双手在双腿之间握住杠铃。","保持背部中立，向下蹬地并伸髋将杠铃贴身拉起。","控制杠铃沿腿部下放，保持髋膝协调。"],"instructionsEn":["Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."],"startImage":"assets/exercise-images/sumo-deadlift-0.jpg","endImage":"assets/exercise-images/sumo-deadlift-1.jpg"},{"id":"glute-bridge","nameZh":"徒手臀桥","nameEn":"Butt Lift (Bridge)","category":"臀部","libraryType":"resistance","level":"初级","equipment":"徒手","force":"推","mechanic":"孤立动作","primaryMuscles":["臀肌"],"secondaryMuscles":["腘绳肌"],"instructionsZh":["仰卧屈膝，双脚与髋同宽踩稳地面。","收紧腹部和臀部，将髋抬至躯干与大腿接近一线。","顶端停顿后缓慢下放，避免用腰部顶起。"],"instructionsEn":["Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.","Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.","Slowly go back to the starting position as you breathe in."],"startImage":"assets/exercise-images/glute-bridge-0.jpg","endImage":"assets/exercise-images/glute-bridge-1.jpg"},{"id":"ab-crunch-machine","nameZh":"器械卷腹","nameEn":"Ab Crunch Machine","category":"核心","libraryType":"resistance","level":"中级","equipment":"固定器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["调整座椅与靠垫，让器械转轴贴合身体自然卷曲方向。","收紧腹部，使肋骨向骨盆靠近完成卷腹。","缓慢回放，避免用手臂拉动把手。"],"instructionsEn":["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.","At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.","After a second pause, slowly return to the starting position as you breathe in.","Repeat the movement for the prescribed amount of repetitions."],"startImage":"assets/exercise-images/ab-crunch-machine-0.jpg","endImage":"assets/exercise-images/ab-crunch-machine-1.jpg"},{"id":"ab-roller","nameZh":"健腹轮","nameEn":"Ab Roller","category":"核心","libraryType":"resistance","level":"中级","equipment":"其他","force":"拉","mechanic":"复合动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":["肩部"],"instructionsZh":["跪姿握住健腹轮，肩膀位于手腕上方，收紧腹部。","缓慢向前滚动，在能保持腰背稳定的范围内停止。","用腹部和背部控制将滚轮拉回，避免塌腰。"],"instructionsEn":["Hold the Ab Roller with both hands and kneel on the floor.","Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."],"startImage":"assets/exercise-images/ab-roller-0.jpg","endImage":"assets/exercise-images/ab-roller-1.jpg"},{"id":"barbell-ab-rollout","nameZh":"杠铃腹肌滚轮","nameEn":"Barbell Ab Rollout","category":"核心","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"拉","mechanic":"复合动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":["下背部","肩部"],"instructionsZh":["双手握住装有稳定杠铃片的杠铃，起始时核心收紧。","缓慢向前滚动，在能保持腰背稳定的范围内停住。","用腹部控制将杠铃拉回，避免塌腰。"],"instructionsEn":["For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.","While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don't, you will work out your shoulders and back more than the abs.","After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/barbell-ab-rollout-0.jpg","endImage":"assets/exercise-images/barbell-ab-rollout-1.jpg"},{"id":"cable-russian-twist","nameZh":"绳索俄罗斯转体","nameEn":"Cable Russian Twists","category":"核心","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["侧对滑轮站稳，双手握把于胸前，髋部保持相对稳定。","以胸椎带动躯干向远离滑轮一侧旋转。","控制回到中间，避免只甩动手臂。"],"instructionsEn":["Connect a standard handle attachment, and position the cable to a middle pulley position.","Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.","Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.","Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.","Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.","Repeat the same movement to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"startImage":"assets/exercise-images/cable-russian-twist-0.jpg","endImage":"assets/exercise-images/cable-russian-twist-1.jpg"},{"id":"cable-reverse-crunch","nameZh":"绳索反向卷腹","nameEn":"Cable Reverse Crunch","category":"核心","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["仰卧并将脚踝连接低位绳索，双手扶稳固定物。","收紧下腹，将膝盖向胸部方向卷起并轻抬骨盆。","缓慢回到起始位，避免借助惯性摆动。"],"instructionsEn":["Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.","Sit down with your feet toward the pulley and attach the cable to your ankles.","Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.","With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.","Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.","Repeat the same movement to failure."],"startImage":"assets/exercise-images/cable-reverse-crunch-0.jpg","endImage":"assets/exercise-images/cable-reverse-crunch-1.jpg"},{"id":"russian-twist","nameZh":"俄罗斯转体","nameEn":"Russian Twist","category":"核心","libraryType":"resistance","level":"中级","equipment":"徒手","force":"拉","mechanic":"复合动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":["下背部"],"instructionsZh":["坐姿屈膝，躯干后倾至稳定角度，双手置于胸前。","保持骨盆相对稳定，以胸椎带动躯干左右转动。","全程控制速度，腰部不适时减小后倾和幅度。"],"instructionsEn":["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.","Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.","Twist your torso to the right side until your arms are parallel with the floor while breathing out.","Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/russian-twist-0.jpg","endImage":"assets/exercise-images/russian-twist-1.jpg"},{"id":"barbell-incline-bench-press","nameZh":"杠铃上斜卧推","nameEn":"Barbell Incline Bench Press - Medium Grip","category":"胸部","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["将靠背调至约 30 度，双脚踩稳，肩胛后收下沉。","将杠铃控制下放至上胸位置。","沿稳定轨迹推回起始位，避免耸肩和臀部离凳。"],"instructionsEn":["Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on you upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"startImage":"assets/exercise-images/barbell-incline-bench-press-0.jpg","endImage":"assets/exercise-images/barbell-incline-bench-press-1.jpg"},{"id":"decline-barbell-bench-press","nameZh":"杠铃下斜卧推","nameEn":"Decline Barbell Bench Press","category":"胸部","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["固定双腿并躺稳下斜凳，握距略宽于肩。","控制杠铃下放至下胸位置。","平稳推起杠铃，保持肩胛稳定。"],"instructionsEn":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.","As you breathe in, come down slowly until you feel the bar on your lower chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"startImage":"assets/exercise-images/decline-barbell-bench-press-0.jpg","endImage":"assets/exercise-images/decline-barbell-bench-press-1.jpg"},{"id":"dumbbell-flyes","nameZh":"哑铃平板飞鸟","nameEn":"Dumbbell Flyes","category":"胸部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"孤立动作","primaryMuscles":["胸部"],"secondaryMuscles":[],"instructionsZh":["仰卧凳上，双手持哑铃举于胸前，手肘微屈。","以弧线向两侧缓慢打开，感受胸部拉伸。","保持肘角不变，用胸部收缩将哑铃带回。"],"instructionsEn":["Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.","Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you're pressing them, but stop and hold just before you lock out. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."],"startImage":"assets/exercise-images/dumbbell-flyes-0.jpg","endImage":"assets/exercise-images/dumbbell-flyes-1.jpg"},{"id":"butterfly-machine","nameZh":"蝴蝶机夹胸","nameEn":"Butterfly","category":"胸部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["胸部"],"secondaryMuscles":[],"instructionsZh":["调整座椅，使把手与胸部中线接近齐平。","肩胛保持稳定，向中间合拢手柄。","顶端收紧胸部后缓慢回放。"],"instructionsEn":["Sit on the machine with your back flat on the pad.","Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.","Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.","Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/butterfly-machine-0.jpg","endImage":"assets/exercise-images/butterfly-machine-1.jpg"},{"id":"leverage-chest-press","nameZh":"器械推胸","nameEn":"Leverage Chest Press","category":"胸部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["坐稳并调整座椅，让把手对准胸部中段。","保持肩胛后收，平稳向前推起手柄。","控制回到起始位，不要让重量片撞击。"],"instructionsEn":["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.","Your chest and head should be up and your shoulder blades retracted. This will be your starting position.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."],"startImage":"assets/exercise-images/leverage-chest-press-0.jpg","endImage":"assets/exercise-images/leverage-chest-press-1.jpg"},{"id":"low-cable-crossover","nameZh":"低位绳索夹胸","nameEn":"Low Cable Crossover","category":"胸部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"推","mechanic":"孤立动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部"],"instructionsZh":["站在低位滑轮之间，双脚前后错开站稳。","双臂沿向上内收的弧线把手柄带至胸前。","缓慢回放，保持胸部与肩胛稳定。"],"instructionsEn":["To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.","Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.","With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.","Return your arms back to the starting position after a brief pause."],"startImage":"assets/exercise-images/low-cable-crossover-0.jpg","endImage":"assets/exercise-images/low-cable-crossover-1.jpg"},{"id":"incline-cable-chest-press","nameZh":"上斜绳索推胸","nameEn":"Incline Cable Chest Press","category":"胸部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["面对低位滑轮，采用前后站姿固定躯干。","从上胸两侧向前上方推起把手。","控制回放，避免腰部后仰。"],"instructionsEn":["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.","After pausing at full extension, return to the starting position, keeping tension on the cables."],"startImage":"assets/exercise-images/incline-cable-chest-press-0.jpg","endImage":"assets/exercise-images/incline-cable-chest-press-1.jpg"},{"id":"decline-smith-press","nameZh":"史密斯机下斜卧推","nameEn":"Decline Smith Press","category":"胸部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["固定双腿并让肩胛贴稳凳面。","控制杠铃下降至下胸附近。","平稳推回，避免肘部完全锁死。"],"instructionsEn":["Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position.","As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso.","After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so.","Repeat the movement for the prescribed amount of repetitions.","When the set is complete, lock the bar back in the rack."],"startImage":"assets/exercise-images/decline-smith-press-0.jpg","endImage":"assets/exercise-images/decline-smith-press-1.jpg"},{"id":"hammer-grip-incline-db-press","nameZh":"中立握上斜哑铃卧推","nameEn":"Hammer Grip Incline DB Bench Press","category":"胸部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["上斜凳坐稳，掌心相对持哑铃于上胸两侧。","以中立握向上推举至手臂接近伸直。","缓慢下放，保持肩胛后收。"],"instructionsEn":["Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.","Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.","Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells."],"startImage":"assets/exercise-images/hammer-grip-incline-db-press-0.jpg","endImage":"assets/exercise-images/hammer-grip-incline-db-press-1.jpg"},{"id":"bent-over-two-dumbbell-row","nameZh":"双哑铃俯身划船","nameEn":"Bent Over Two-Dumbbell Row","category":"背部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"拉","mechanic":"复合动作","primaryMuscles":["中背部"],"secondaryMuscles":["肱二头肌","背阔肌","肩部"],"instructionsZh":["屈髋俯身并保持脊柱中立，双哑铃自然下垂。","双肘向后拉，将哑铃带向髋部两侧。","轻收肩胛后控制下放。"],"instructionsEn":["With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/bent-over-two-dumbbell-row-0.jpg","endImage":"assets/exercise-images/bent-over-two-dumbbell-row-1.jpg"},{"id":"tbar-row-handle","nameZh":"T 杠划船","nameEn":"T-Bar Row with Handle","category":"背部","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"拉","mechanic":"复合动作","primaryMuscles":["中背部"],"secondaryMuscles":["肱二头肌","背阔肌"],"instructionsZh":["采用稳定站姿俯身握住把手，核心收紧。","用肘部向后带动把手拉向下腹。","缓慢下放，避免圆背或耸肩。"],"instructionsEn":["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.","Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.","Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.","Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.","After a brief pause, return to the starting position."],"startImage":"assets/exercise-images/tbar-row-handle-0.jpg","endImage":"assets/exercise-images/tbar-row-handle-1.jpg"},{"id":"reverse-grip-bent-over-row","nameZh":"反握杠铃俯身划船","nameEn":"Reverse Grip Bent-Over Rows","category":"背部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"拉","mechanic":"复合动作","primaryMuscles":["中背部"],"secondaryMuscles":["肱二头肌","背阔肌","肩部"],"instructionsZh":["反握杠铃并屈髋俯身，背部保持中立。","将杠铃拉向下腹，肘部贴近躯干。","控制下放，避免躯干摆动。"],"instructionsEn":["Stand erect while holding a barbell with a supinated grip (palms facing up).","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/reverse-grip-bent-over-row-0.jpg","endImage":"assets/exercise-images/reverse-grip-bent-over-row-1.jpg"},{"id":"leverage-high-row","nameZh":"高位器械划船","nameEn":"Leverage High Row","category":"背部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"拉","mechanic":"复合动作","primaryMuscles":["中背部"],"secondaryMuscles":["背阔肌"],"instructionsZh":["调整座椅和胸垫，胸部贴稳支撑。","向后下方拉动把手，带动肩胛后收。","缓慢回放，保持颈部放松。"],"instructionsEn":["Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position.","For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."],"startImage":"assets/exercise-images/leverage-high-row-0.jpg","endImage":"assets/exercise-images/leverage-high-row-1.jpg"},{"id":"smith-machine-bent-over-row","nameZh":"史密斯机俯身划船","nameEn":"Smith Machine Bent Over Row","category":"背部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"拉","mechanic":"复合动作","primaryMuscles":["中背部"],"secondaryMuscles":["肱二头肌","背阔肌","肩部"],"instructionsZh":["站在杠下屈髋俯身，双手正握固定杠铃。","将杠铃沿稳定轨迹拉向腹部。","停顿后控制下降，躯干不借力摆动。"],"instructionsEn":["Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up.","Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/smith-machine-bent-over-row-0.jpg","endImage":"assets/exercise-images/smith-machine-bent-over-row-1.jpg"},{"id":"vbar-pulldown","nameZh":"V 把高位下拉","nameEn":"V-Bar Pulldown","category":"背部","libraryType":"resistance","level":"中级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["背阔肌"],"secondaryMuscles":["肱二头肌","中背部","肩部"],"instructionsZh":["坐稳并固定大腿，双手握住 V 把。","先下沉肩胛，再将把手拉向上胸。","控制回放至手臂接近伸直。"],"instructionsEn":["Sit down on a pull-down machine with a V-Bar attached to the top pulley.","Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.","Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.","After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.","Repeat for the prescribed number of repetitions."],"startImage":"assets/exercise-images/vbar-pulldown-0.jpg","endImage":"assets/exercise-images/vbar-pulldown-1.jpg"},{"id":"kneeling-high-pulley-row","nameZh":"跪姿高位绳索划船","nameEn":"Kneeling High Pulley Row","category":"背部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["背阔肌"],"secondaryMuscles":["肱二头肌","中背部"],"instructionsZh":["面对高位滑轮跪稳，双手握住把手。","将肘部向身体两侧和后方拉动。","收紧背部后缓慢回到起始位。"],"instructionsEn":["Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position.","Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out.","After pausing briefly, slowly return to the starting position."],"startImage":"assets/exercise-images/kneeling-high-pulley-row-0.jpg","endImage":"assets/exercise-images/kneeling-high-pulley-row-1.jpg"},{"id":"seated-one-arm-cable-row","nameZh":"单臂坐姿绳索划船","nameEn":"Seated One-arm Cable Pulley Rows","category":"背部","libraryType":"resistance","level":"中级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["中背部"],"secondaryMuscles":["肱二头肌","背阔肌","斜方肌"],"instructionsZh":["坐稳并保持躯干正对前方，单手握住把手。","将手肘向髋部方向拉回。","控制手臂伸展，避免身体扭转。"],"instructionsEn":["To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.","With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it as you rotate the wrist, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torso). Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard.","Hold that contraction for a second and slowly go back to the original position while breathing in. Tip: Remember to rotate the wrist as you go back to the starting position so that the palms are facing down again.","Repeat for the recommended amount of repetitions and then perform the same movement with the right hand."],"startImage":"assets/exercise-images/seated-one-arm-cable-row-0.jpg","endImage":"assets/exercise-images/seated-one-arm-cable-row-1.jpg"},{"id":"straight-arm-pulldown","nameZh":"直臂下拉","nameEn":"Straight-Arm Pulldown","category":"背部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["背阔肌"],"secondaryMuscles":[],"instructionsZh":["面对高位滑轮站稳，手肘保持微屈。","固定肘角度，将直杆拉向大腿前侧。","缓慢回放，避免躯干后仰。"],"instructionsEn":["You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.","Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.","While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.","While keeping the arms straight, go back to the starting position while breathing in.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/straight-arm-pulldown-0.jpg","endImage":"assets/exercise-images/straight-arm-pulldown-1.jpg"},{"id":"alternating-cable-shoulder-press","nameZh":"交替绳索肩推","nameEn":"Alternating Cable Shoulder Press","category":"肩部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"推","mechanic":"复合动作","primaryMuscles":["肩部"],"secondaryMuscles":["肱三头肌"],"instructionsZh":["站在滑轮间，核心收紧，将把手置于肩侧。","单侧向上推举，保持躯干不侧倾。","控制下降后换侧完成。"],"instructionsEn":["Move the cables to the bottom of the tower and select an appropriate weight.","Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.","Keeping your head and chest up, extend through the elbow to press one side directly over head.","After pausing at the top, return to the starting position and repeat on the opposite side."],"startImage":"assets/exercise-images/alternating-cable-shoulder-press-0.jpg","endImage":"assets/exercise-images/alternating-cable-shoulder-press-1.jpg"},{"id":"barbell-rear-delt-row","nameZh":"杠铃后束划船","nameEn":"Barbell Rear Delt Row","category":"肩部","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"拉","mechanic":"复合动作","primaryMuscles":["肩部"],"secondaryMuscles":["肱二头肌","背阔肌","中背部"],"instructionsZh":["俯身握杠，手肘向两侧打开。","将杠铃拉向上腹部，感受肩后束收缩。","缓慢下放，保持颈部放松。"],"instructionsEn":["Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.","Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter \"T\". Now you are ready to begin the exercise.","While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.","Slowly go back to the initial position as you breathe in.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/barbell-rear-delt-row-0.jpg","endImage":"assets/exercise-images/barbell-rear-delt-row-1.jpg"},{"id":"bent-over-dumbbell-rear-delt-raise","nameZh":"俯身哑铃后束飞鸟","nameEn":"Bent Over Dumbbell Rear Delt Raise With Head On Bench","category":"肩部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":[],"instructionsZh":["额头轻贴凳面支撑，双哑铃自然下垂。","保持手肘微屈，向两侧抬起哑铃。","在肩后束收紧处停顿后控制下放。"],"instructionsEn":["Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.","While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.","Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.","After a one second contraction at the top, slowly lower the dumbbells back to the starting position.","Repeat the recommended amount of repetitions."],"startImage":"assets/exercise-images/bent-over-dumbbell-rear-delt-raise-0.jpg","endImage":"assets/exercise-images/bent-over-dumbbell-rear-delt-raise-1.jpg"},{"id":"cable-seated-lateral-raise","nameZh":"坐姿绳索侧平举","nameEn":"Cable Seated Lateral Raise","category":"肩部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":["中背部","斜方肌"],"instructionsZh":["坐稳并从身体侧方握住低位滑轮把手。","以肩部带动手臂向侧上方抬起至接近肩高。","缓慢下放，避免耸肩。"],"instructionsEn":["Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.","Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.","Bend forward while keeping your back flat and rest your torso on the thighs.","Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.","While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.","Slowly lower your arms to the starting position as you inhale.","Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise."],"startImage":"assets/exercise-images/cable-seated-lateral-raise-0.jpg","endImage":"assets/exercise-images/cable-seated-lateral-raise-1.jpg"},{"id":"cable-shoulder-press","nameZh":"绳索肩推","nameEn":"Cable Shoulder Press","category":"肩部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"推","mechanic":"复合动作","primaryMuscles":["肩部"],"secondaryMuscles":["肱三头肌"],"instructionsZh":["双手握低位滑轮把手置于肩侧，站姿稳定。","向上推举至头顶上方。","控制回到肩侧，保持肋骨不过度外翻。"],"instructionsEn":["Move the cables to the bottom of the towers and select an appropriate weight.","Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.","Keeping your head and chest up, extend through the elbow to press the handles directly over head.","After pausing at the top, return to the starting position and repeat."],"startImage":"assets/exercise-images/cable-shoulder-press-0.jpg","endImage":"assets/exercise-images/cable-shoulder-press-1.jpg"},{"id":"dumbbell-scaptation","nameZh":"哑铃肩胛面举","nameEn":"Dumbbell Scaption","category":"肩部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":["斜方肌"],"instructionsZh":["双手持轻哑铃站稳，手臂位于身体前侧约 30 度。","沿肩胛面平稳抬起至肩高附近。","缓慢下降，保持肩胛自然上旋。"],"instructionsEn":["This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.","Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.","Continue until your arms are parallel to the ground, and then return to the starting position."],"startImage":"assets/exercise-images/dumbbell-scaptation-0.jpg","endImage":"assets/exercise-images/dumbbell-scaptation-1.jpg"},{"id":"one-arm-dumbbell-shoulder-press","nameZh":"单臂哑铃肩推","nameEn":"Dumbbell One-Arm Shoulder Press","category":"肩部","libraryType":"resistance","level":"中级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["肩部"],"secondaryMuscles":["肱三头肌"],"instructionsZh":["坐姿或站姿将哑铃置于单侧肩旁，核心收紧。","沿稳定轨迹向上推举。","缓慢回到起始位，完成后换侧。"],"instructionsEn":["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.","Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.","Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.","As you exhale, push the dumbbell up until your arm is fully extended.","After a second pause, slowly come down back to the starting position as you inhale.","Repeat for the recommended amount of repetitions and then switch arms."],"startImage":"assets/exercise-images/one-arm-dumbbell-shoulder-press-0.jpg","endImage":"assets/exercise-images/one-arm-dumbbell-shoulder-press-1.jpg"},{"id":"front-cable-raise","nameZh":"绳索前平举","nameEn":"Front Cable Raise","category":"肩部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"推","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":[],"instructionsZh":["背对低位滑轮站稳，双手握把置于大腿前。","以肩前束将把手向前抬至接近肩高。","控制下降，不用躯干甩动。"],"instructionsEn":["Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.","Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms' length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.","Now as you inhale lower the arm back down slowly to the starting position.","Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one."],"startImage":"assets/exercise-images/front-cable-raise-0.jpg","endImage":"assets/exercise-images/front-cable-raise-1.jpg"},{"id":"alternate-incline-dumbbell-curl","nameZh":"上斜交替哑铃弯举","nameEn":"Alternate Incline Dumbbell Curl","category":"手臂","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":["前臂"],"instructionsZh":["坐在上斜凳上，双臂自然下垂，掌心向前。","单侧屈肘将哑铃弯向肩部。","缓慢下降后换侧，保持上臂稳定。"],"instructionsEn":["Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.","While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbell back to starting position as your breathe in.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."],"startImage":"assets/exercise-images/alternate-incline-dumbbell-curl-0.jpg","endImage":"assets/exercise-images/alternate-incline-dumbbell-curl-1.jpg"},{"id":"cable-preacher-curl","nameZh":"绳索牧师凳弯举","nameEn":"Cable Preacher Curl","category":"手臂","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":["前臂"],"instructionsZh":["上臂贴稳牧师凳垫并握住低位绳索把手。","固定上臂完成屈肘弯举。","缓慢伸肘回放，底部保留微屈。"],"instructionsEn":["Place a preacher bench about 2 feet in front of a pulley machine.","Attach a straight bar to the low pulley.","Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.","Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.","Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.","Now slowly lower the weight to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/cable-preacher-curl-0.jpg","endImage":"assets/exercise-images/cable-preacher-curl-1.jpg"},{"id":"cross-body-hammer-curl","nameZh":"交叉锤式弯举","nameEn":"Cross Body Hammer Curl","category":"手臂","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":["前臂"],"instructionsZh":["站姿中立握哑铃，手臂置于身体两侧。","将一侧哑铃斜向弯举至对侧肩前。","控制下放后换侧，避免躯干借力。"],"instructionsEn":["Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.","While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.","Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.","Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm."],"startImage":"assets/exercise-images/cross-body-hammer-curl-0.jpg","endImage":"assets/exercise-images/cross-body-hammer-curl-1.jpg"},{"id":"dumbbell-alternate-bicep-curl","nameZh":"交替哑铃弯举","nameEn":"Dumbbell Alternate Bicep Curl","category":"手臂","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":["前臂"],"instructionsZh":["站稳后双手持哑铃，手臂自然下垂。","单侧屈肘并旋转掌心向上完成弯举。","缓慢下降后换侧，保持上臂贴近身体。"],"instructionsEn":["Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.","While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."],"startImage":"assets/exercise-images/dumbbell-alternate-bicep-curl-0.jpg","endImage":"assets/exercise-images/dumbbell-alternate-bicep-curl-1.jpg"},{"id":"ez-bar-curl","nameZh":"曲杆弯举","nameEn":"EZ-Bar Curl","category":"手臂","libraryType":"resistance","level":"初级","equipment":"曲杆","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":[],"instructionsZh":["双手握曲杆站稳，肘部贴近躯干。","只通过屈肘将曲杆弯举至胸前。","平稳下放，避免后仰甩动。"],"instructionsEn":["Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.","Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.","Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.","Then inhale and slowly lower the bar back to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/ez-bar-curl-0.jpg","endImage":"assets/exercise-images/ez-bar-curl-1.jpg"},{"id":"machine-bicep-curl","nameZh":"器械二头弯举","nameEn":"Machine Bicep Curl","category":"手臂","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":[],"instructionsZh":["调整座椅，让上臂贴稳器械垫。","屈肘拉起把手，感受肱二头肌收缩。","控制回放，不让重量片撞击。"],"instructionsEn":["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.","Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.","Pause at the top of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."],"startImage":"assets/exercise-images/machine-bicep-curl-0.jpg","endImage":"assets/exercise-images/machine-bicep-curl-1.jpg"},{"id":"high-cable-curls","nameZh":"高位绳索弯举","nameEn":"High Cable Curls","category":"手臂","libraryType":"resistance","level":"中级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":[],"instructionsZh":["站在双高位滑轮之间，双臂张开握住把手。","固定上臂，向头部方向屈肘弯举。","顶端收紧后缓慢伸肘。"],"instructionsEn":["Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.","Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.","Slowly bring back the arms to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/high-cable-curls-0.jpg","endImage":"assets/exercise-images/high-cable-curls-1.jpg"},{"id":"close-grip-barbell-bench-press","nameZh":"窄握杠铃卧推","nameEn":"Close-Grip Barbell Bench Press","category":"手臂","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["肱三头肌"],"secondaryMuscles":["胸部","肩部"],"instructionsZh":["平躺凳上，双手以略窄于肩的握距握杠。","控制杠铃下放至下胸附近，肘部贴近躯干。","以肱三头肌发力推回起始位。"],"instructionsEn":["Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"startImage":"assets/exercise-images/close-grip-barbell-bench-press-0.jpg","endImage":"assets/exercise-images/close-grip-barbell-bench-press-1.jpg"},{"id":"machine-triceps-extension","nameZh":"器械三头伸展","nameEn":"Machine Triceps Extension","category":"手臂","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"孤立动作","primaryMuscles":["肱三头肌"],"secondaryMuscles":[],"instructionsZh":["调整座椅并固定上臂于支撑垫。","伸肘推开手柄至肱三头肌收紧。","缓慢屈肘回放，避免耸肩。"],"instructionsEn":["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.","Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.","Pause at the completion of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."],"startImage":"assets/exercise-images/machine-triceps-extension-0.jpg","endImage":"assets/exercise-images/machine-triceps-extension-1.jpg"},{"id":"barbell-hack-squat","nameZh":"杠铃哈克深蹲","nameEn":"Barbell Hack Squat","category":"腿部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","前臂","腘绳肌"],"instructionsZh":["杠铃置于身体后方，双脚站稳并保持背部自然中立。","屈膝屈髋下蹲，让杠铃沿小腿后侧下降。","通过脚掌发力站起，避免膝盖内扣。"],"instructionsEn":["Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.","While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.","Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/barbell-hack-squat-0.jpg","endImage":"assets/exercise-images/barbell-hack-squat-1.jpg"},{"id":"barbell-walking-lunge","nameZh":"杠铃行走箭步蹲","nameEn":"Barbell Walking Lunge","category":"腿部","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌"],"instructionsZh":["将杠铃稳放在上背，向前迈出一大步。","控制下沉至双膝弯曲，前膝保持对线。","通过前脚发力站起并连续向前换腿。"],"instructionsEn":["Begin standing with your feet shoulder width apart and a barbell across your upper back.","Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."],"startImage":"assets/exercise-images/barbell-walking-lunge-0.jpg","endImage":"assets/exercise-images/barbell-walking-lunge-1.jpg"},{"id":"dumbbell-rear-lunge","nameZh":"哑铃后撤箭步蹲","nameEn":"Dumbbell Rear Lunge","category":"腿部","libraryType":"resistance","level":"中级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌"],"instructionsZh":["双手持哑铃站稳，一脚向后撤步。","前腿屈膝下沉，保持躯干直立。","通过前脚全掌发力回到站姿并换边。"],"instructionsEn":["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.","Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.","Now repeat with the opposite leg."],"startImage":"assets/exercise-images/dumbbell-rear-lunge-0.jpg","endImage":"assets/exercise-images/dumbbell-rear-lunge-1.jpg"},{"id":"dumbbell-squat","nameZh":"哑铃深蹲","nameEn":"Dumbbell Squat","category":"腿部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌","下背部"],"instructionsZh":["双手持哑铃于身体两侧，双脚与肩同宽。","屈髋屈膝下蹲，膝盖跟随脚尖方向。","保持躯干稳定，蹬地站回起始位。"],"instructionsEn":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.","Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/dumbbell-squat-0.jpg","endImage":"assets/exercise-images/dumbbell-squat-1.jpg"},{"id":"front-squat-clean-grip","nameZh":"杠铃前蹲","nameEn":"Front Squat (Clean Grip)","category":"腿部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["腹部肌群","臀肌","腘绳肌"],"instructionsZh":["将杠铃置于前三角肌，采用翻腕握法保持肘部抬高。","保持胸廓自然抬起，屈髋屈膝下蹲。","通过全脚掌发力站起，避免膝盖内扣。"],"instructionsEn":["To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.","Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.","Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.","Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position."],"startImage":"assets/exercise-images/front-squat-clean-grip-0.jpg","endImage":"assets/exercise-images/front-squat-clean-grip-1.jpg"},{"id":"good-morning","nameZh":"杠铃早安式","nameEn":"Good Morning","category":"腿部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["腘绳肌"],"secondaryMuscles":["腹部肌群","臀肌","下背部"],"instructionsZh":["将轻杠铃置于上背，膝盖保持微屈。","向后送髋并让躯干前倾，背部保持中立。","收紧臀腿伸髋站起，避免圆背。"],"instructionsEn":["Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.","Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.","Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position."],"startImage":"assets/exercise-images/good-morning-0.jpg","endImage":"assets/exercise-images/good-morning-1.jpg"},{"id":"barbell-step-ups","nameZh":"杠铃登台阶","nameEn":"Barbell Step Ups","category":"腿部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌","股四头肌"],"instructionsZh":["杠铃稳放在上背，选择牢固且高度合适的台阶。","一脚全掌踩上台阶，通过踩台腿发力站直。","控制下台，完成后换侧。"],"instructionsEn":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.","Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.","Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.","Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg."],"startImage":"assets/exercise-images/barbell-step-ups-0.jpg","endImage":"assets/exercise-images/barbell-step-ups-1.jpg"},{"id":"smith-machine-squat","nameZh":"史密斯机深蹲","nameEn":"Smith Machine Squat","category":"腿部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌","下背部"],"instructionsZh":["肩背贴稳杠铃，双脚置于杠前的舒适位置。","沿固定轨迹控制下蹲，膝盖跟随脚尖方向。","蹬地站起，保持骨盆与躯干稳定。"],"instructionsEn":["To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/smith-machine-squat-0.jpg","endImage":"assets/exercise-images/smith-machine-squat-1.jpg"},{"id":"seated-calf-raise","nameZh":"坐姿提踵","nameEn":"Seated Calf Raise","category":"腿部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"孤立动作","primaryMuscles":["小腿"],"secondaryMuscles":[],"instructionsZh":["前脚掌踩稳踏板，膝盖置于压垫下。","抬起脚跟至小腿充分收缩。","缓慢下降到舒适拉伸位置。"],"instructionsEn":["Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.","Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.","Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.","Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.","Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/seated-calf-raise-0.jpg","endImage":"assets/exercise-images/seated-calf-raise-1.jpg"},{"id":"calf-press","nameZh":"腿举机提踵","nameEn":"Calf Press On The Leg Press Machine","category":"腿部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"孤立动作","primaryMuscles":["小腿"],"secondaryMuscles":[],"instructionsZh":["在腿举机上仅以前脚掌踩住踏板，膝盖保持微屈。","通过踝关节跖屈推起踏板。","缓慢回到小腿拉伸位置，避免锁死膝盖。"],"instructionsEn":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/calf-press-0.jpg","endImage":"assets/exercise-images/calf-press-1.jpg"},{"id":"cable-pull-through","nameZh":"绳索拉臀","nameEn":"Pull Through","category":"臀部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["臀肌"],"secondaryMuscles":["腘绳肌","下背部"],"instructionsZh":["背对低位滑轮站稳，双手从两腿间握住绳索。","向后送髋感受臀腿拉伸，再伸髋站直。","顶端收紧臀部，避免用腰部后仰。"],"instructionsEn":["Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.","Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips."],"startImage":"assets/exercise-images/cable-pull-through-0.jpg","endImage":"assets/exercise-images/cable-pull-through-1.jpg"},{"id":"kneeling-squat","nameZh":"跪姿杠铃深蹲","nameEn":"Kneeling Squat","category":"臀部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["臀肌"],"secondaryMuscles":["腹部肌群","腘绳肌","下背部"],"instructionsZh":["跪姿将杠铃稳放在上背，双膝置于软垫上。","控制髋部向后坐，保持躯干稳定。","通过臀部伸髋回到直立跪姿。"],"instructionsEn":["Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight.","With your head looking forward, sit back with your butt until you touch your calves.","Reverse the motion, returning the torso to an upright position."],"startImage":"assets/exercise-images/kneeling-squat-0.jpg","endImage":"assets/exercise-images/kneeling-squat-1.jpg"},{"id":"glute-kickback","nameZh":"徒手臀部后踢","nameEn":"Glute Kickback","category":"臀部","libraryType":"resistance","level":"初级","equipment":"徒手","force":"推","mechanic":"复合动作","primaryMuscles":["臀肌"],"secondaryMuscles":["腘绳肌"],"instructionsZh":["四点跪姿，双手位于肩下，核心轻收紧。","屈膝将一侧腿向后上方伸髋。","臀部收紧后控制回到起始位并换边。"],"instructionsEn":["Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.","Go back to the initial position as you inhale and now repeat with the left leg.","Continue to alternate legs until all of the recommended repetitions have been performed."],"startImage":"assets/exercise-images/glute-kickback-0.jpg","endImage":"assets/exercise-images/glute-kickback-1.jpg"},{"id":"hip-extension-bands","nameZh":"弹力带髋伸展","nameEn":"Hip Extension with Bands","category":"臀部","libraryType":"resistance","level":"初级","equipment":"弹力带","force":"推","mechanic":"复合动作","primaryMuscles":["臀肌"],"secondaryMuscles":["腘绳肌"],"instructionsZh":["将弹力带固定在脚踝和身后低位固定点之间。","保持骨盆朝前，将工作腿向后伸展。","臀部收紧后缓慢回位并换边。"],"instructionsEn":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Facing the attachment point of the band, hold on to the column to stabilize yourself.","Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.","Return the leg to the starting position."],"startImage":"assets/exercise-images/hip-extension-bands-0.jpg","endImage":"assets/exercise-images/hip-extension-bands-1.jpg"},{"id":"hip-lift-band","nameZh":"弹力带臀桥","nameEn":"Hip Lift with Band","category":"臀部","libraryType":"resistance","level":"初级","equipment":"弹力带","force":"推","mechanic":"复合动作","primaryMuscles":["臀肌"],"secondaryMuscles":["小腿","腘绳肌"],"instructionsZh":["仰卧屈膝，将弹力带置于膝盖上方。","保持膝盖轻向外推，同时抬髋。","顶端收紧臀部后缓慢下放。"],"instructionsEn":["After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn't have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won't move.","Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.","Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.","Pause at the top of the motion, and return to the starting position."],"startImage":"assets/exercise-images/hip-lift-band-0.jpg","endImage":"assets/exercise-images/hip-lift-band-1.jpg"},{"id":"physioball-hip-bridge","nameZh":"健身球臀桥","nameEn":"Physioball Hip Bridge","category":"臀部","libraryType":"resistance","level":"初级","equipment":"健身球","force":"推","mechanic":"复合动作","primaryMuscles":["臀肌"],"secondaryMuscles":["腘绳肌"],"instructionsZh":["仰卧将小腿置于健身球上，双臂平放保持稳定。","通过脚跟和臀部发力抬起髋部。","保持球不滚动，控制下放回起始位。"],"instructionsEn":["Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position.","Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge.","Pause at the top of the motion and return to the starting position."],"startImage":"assets/exercise-images/physioball-hip-bridge-0.jpg","endImage":"assets/exercise-images/physioball-hip-bridge-1.jpg"},{"id":"barbell-side-bend","nameZh":"杠铃侧屈","nameEn":"Barbell Side Bend","category":"核心","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":["下背部"],"instructionsZh":["单手或背部稳定杠铃，双脚站稳。","仅从躯干侧向缓慢屈曲，保持髋部稳定。","以侧腹发力回到中立，不借助摆动。"],"instructionsEn":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/barbell-side-bend-0.jpg","endImage":"assets/exercise-images/barbell-side-bend-1.jpg"},{"id":"cable-seated-crunch","nameZh":"坐姿绳索卷腹","nameEn":"Cable Seated Crunch","category":"核心","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["坐稳后双手固定绳索于头部两侧。","让肋骨向骨盆靠近，完成躯干卷曲。","缓慢回放，避免用手臂猛拉。"],"instructionsEn":["Seat on a flat bench with your back facing a high pulley.","Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.","With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.","As you inhale, go back to the initial position slowly.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/cable-seated-crunch-0.jpg","endImage":"assets/exercise-images/cable-seated-crunch-1.jpg"},{"id":"dumbbell-side-bend","nameZh":"哑铃侧屈","nameEn":"Dumbbell Side Bend","category":"核心","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["单手持哑铃站稳，另一手可置于髋部。","向持铃侧缓慢侧屈，保持身体在同一平面。","用侧腹控制回到直立，完成后换边。"],"instructionsEn":["Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions and then change hands."],"startImage":"assets/exercise-images/dumbbell-side-bend-0.jpg","endImage":"assets/exercise-images/dumbbell-side-bend-1.jpg"},{"id":"pallof-press","nameZh":"帕洛夫抗旋转推","nameEn":"Pallof Press","category":"核心","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":["胸部","肩部","肱三头肌"],"instructionsZh":["侧对绳索站稳，双手在胸前握住把手。","向前推出把手并抵抗绳索带来的旋转。","停顿后控制收回，躯干保持正对前方。"],"instructionsEn":["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.","With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.","With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.","Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.","Hold the repetition for several seconds before returning to the starting position.","At the conclusion of the set, repeat facing the other direction."],"startImage":"assets/exercise-images/pallof-press-0.jpg","endImage":"assets/exercise-images/pallof-press-1.jpg"},{"id":"kneeling-cable-oblique-crunch","nameZh":"跪姿绳索交替侧卷腹","nameEn":"Kneeling Cable Crunch With Alternating Oblique Twists","category":"核心","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["跪于高位滑轮前，双手将绳索置于头侧。","卷腹时交替向左右侧带动胸廓转动。","控制回到中间，避免只用手臂拉动。"],"instructionsEn":["Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.","Grab the rope with both hands and kneel approximately two feet back from the tower.","Position the rope behind your head with your hands by your ears.","Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.","Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.","Repeat the same downward movement until you're halfway down, at which time you'll begin rotating one of your elbows to the opposite knee.","Again, pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.","Repeat the same movement as before, but alternate the other elbow to the opposite knee.","Continue this series of movements to failure."],"startImage":"assets/exercise-images/kneeling-cable-oblique-crunch-0.jpg","endImage":"assets/exercise-images/kneeling-cable-oblique-crunch-1.jpg"},{"id":"landmine-180","nameZh":"地雷管 180 度转体","nameEn":"Landmine 180's","category":"核心","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"拉","mechanic":"复合动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":["臀肌","下背部","肩部"],"instructionsZh":["双手握住地雷管杠铃端，双脚与肩同宽站稳。","控制杠铃端在身体两侧画弧移动。","让胸椎带动旋转，保持髋部稳定。"],"instructionsEn":["Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.","Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.","Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.","Reverse the motion to swing the weight all the way to the opposite side.","Continue alternating the movement until the set is complete."],"startImage":"assets/exercise-images/landmine-180-0.jpg","endImage":"assets/exercise-images/landmine-180-1.jpg"},{"id":"bosu-cable-crunch-side-bend","nameZh":"平衡球绳索侧卷腹","nameEn":"Bosu Ball Cable Crunch With Side Bends","category":"核心","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["在平衡球上稳定坐好并握住绳索。","先卷腹再向一侧轻微侧屈，动作保持可控。","回到中间后换侧，避免失去平衡。"],"instructionsEn":["Connect a standard handle to each arm of a cable machine, and position them in the most downward position.","Grab a Bosu Ball and position it in front and center of the cable machine.","Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.","With both hands, reach back and grab the handle of each cable.","With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.","Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.","Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.","Repeat the same series of movements to failure.","Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.","Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques."],"startImage":"assets/exercise-images/bosu-cable-crunch-side-bend-0.jpg","endImage":"assets/exercise-images/bosu-cable-crunch-side-bend-1.jpg"},{"id":"barbell-glute-bridge","nameZh":"杠铃臀桥","nameEn":"Barbell Glute Bridge","category":"臀部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["臀肌"],"secondaryMuscles":["小腿","腘绳肌"],"instructionsZh":["仰卧屈膝，将杠铃横置于髋部并垫好保护垫。","以脚跟和臀部发力抬髋至舒适高度。","顶部收紧臀部后缓慢下放，避免腰部代偿。"],"instructionsEn":["Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.","Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.","Extend as far as possible, then reverse the motion to return to the starting position."],"startImage":"assets/exercise-images/barbell-glute-bridge-0.jpg","endImage":"assets/exercise-images/barbell-glute-bridge-1.jpg"},{"id":"barbell-ab-rollout-knees","nameZh":"跪姿杠铃滚轮","nameEn":"Barbell Ab Rollout - On Knees","category":"核心","libraryType":"resistance","level":"高级","equipment":"杠铃","force":"拉","mechanic":"复合动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":["下背部","肩部"],"instructionsZh":["跪姿双手握住装有稳定杠铃片的杠铃，收紧腹部。","缓慢向前滚动，在腰背能保持稳定的范围内停止。","控制杠铃拉回起始位，避免腰椎塌陷。"],"instructionsEn":["Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.","Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."],"startImage":"assets/exercise-images/barbell-ab-rollout-knees-0.jpg","endImage":"assets/exercise-images/barbell-ab-rollout-knees-1.jpg"},{"id":"arm-circles","nameZh":"手臂绕环","nameEn":"Arm Circles","category":"热身","libraryType":"warmup","level":"初级","equipment":"未提供","force":"推","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":["斜方肌"],"instructionsZh":["站立并让双脚与髋同宽，双臂自然张开至身体两侧。","以肩关节为轴向前画小圆，逐渐增加幅度。","换方向重复，动作平稳，避免耸肩或甩动躯干。"],"instructionsEn":["Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.","Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.","Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction."],"startImage":"assets/exercise-images/arm-circles-0.jpg","endImage":"assets/exercise-images/arm-circles-1.jpg"},{"id":"standing-hip-circles","nameZh":"站姿髋绕环","nameEn":"Standing Hip Circles","category":"热身","libraryType":"warmup","level":"初级","equipment":"徒手","force":"拉","mechanic":"孤立动作","primaryMuscles":["髋外展肌群"],"secondaryMuscles":["髋内收肌群"],"instructionsZh":["单脚站稳，可轻扶固定物保持平衡。","抬起另一侧膝盖，以髋关节为轴缓慢画圈。","完成一侧后换边，保持骨盆稳定，不追求过大幅度。"],"instructionsEn":["Begin standing on one leg, holding to a vertical support.","Raise the unsupported knee to 90 degrees. This will be your starting position.","Open the hip as far as possible, attempting to make a big circle with your knee.","Perform this movement slowly for a number of repetitions, and repeat on the other side."],"startImage":"assets/exercise-images/standing-hip-circles-0.jpg","endImage":"assets/exercise-images/standing-hip-circles-1.jpg"},{"id":"knee-circles","nameZh":"膝关节绕环","nameEn":"Knee Circles","category":"热身","libraryType":"warmup","level":"初级","equipment":"徒手","force":"拉","mechanic":"复合动作","primaryMuscles":["小腿"],"secondaryMuscles":["腘绳肌","股四头肌"],"instructionsZh":["双脚并拢站立，膝盖微屈，双手轻扶膝部。","让双膝在舒适范围内缓慢画小圆。","完成一个方向后换方向，始终保持脚掌稳定贴地。"],"instructionsEn":["Stand with your legs together and hands by your waist.","Now move your knees in a circular motion as you breathe normally.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/knee-circles-0.jpg","endImage":"assets/exercise-images/knee-circles-1.jpg"},{"id":"ankle-circles","nameZh":"踝关节绕环","nameEn":"Ankle Circles","category":"热身","libraryType":"warmup","level":"初级","equipment":"未提供","force":"拉","mechanic":"孤立动作","primaryMuscles":["小腿"],"secondaryMuscles":[],"instructionsZh":["坐姿或扶墙站姿，让一侧脚离地。","以踝关节为轴缓慢画圈，保持小腿稳定。","完成一个方向后换方向，再练习另一侧。"],"instructionsEn":["Use a sturdy object like a squat rack to hold yourself.","Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.","When you are done with the right foot, then repeat with the left leg."],"startImage":"assets/exercise-images/ankle-circles-0.jpg","endImage":"assets/exercise-images/ankle-circles-1.jpg"},{"id":"triceps-stretch","nameZh":"肱三头肌拉伸","nameEn":"Triceps Stretch","category":"拉伸","libraryType":"stretch","level":"初级","equipment":"未提供","force":"静态","mechanic":"孤立动作","primaryMuscles":["肱三头肌"],"secondaryMuscles":["背阔肌"],"instructionsZh":["一侧手臂抬过头顶并屈肘，让手掌靠近上背部。","另一只手轻扶肘部，向内下方施加轻柔压力。","感到上臂后侧与背阔肌轻微牵拉时保持 20-30 秒，再换侧。"],"instructionsEn":["Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides."],"startImage":"assets/exercise-images/triceps-stretch-0.jpg","endImage":"assets/exercise-images/triceps-stretch-1.jpg"},{"id":"upper-back-stretch","nameZh":"上背部拉伸","nameEn":"Upper Back Stretch","category":"拉伸","libraryType":"stretch","level":"初级","equipment":"未提供","force":"静态","mechanic":"未提供","primaryMuscles":["中背部"],"secondaryMuscles":["中背部"],"instructionsZh":["双手在胸前相扣并向前伸直，膝盖微屈站稳。","轻轻向前推手，让肩胛骨自然分开。","保持颈部放松、正常呼吸，感到上背部轻微牵拉即可。"],"instructionsEn":["Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward."],"startImage":"assets/exercise-images/upper-back-stretch-0.jpg","endImage":"assets/exercise-images/upper-back-stretch-1.jpg"},{"id":"kneeling-hip-flexor","nameZh":"半跪髋屈肌拉伸","nameEn":"Kneeling Hip Flexor","category":"拉伸","libraryType":"stretch","level":"初级","equipment":"未提供","force":"静态","mechanic":"孤立动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["股四头肌"],"instructionsZh":["一膝跪地，另一脚踩稳在前，骨盆保持正对前方。","轻收紧跪地侧臀部，让骨盆轻微后倾后缓慢前移。","感到髋前侧轻微牵拉时保持 20-30 秒，再换边。"],"instructionsEn":["Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.","Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side."],"startImage":"assets/exercise-images/kneeling-hip-flexor-0.jpg","endImage":"assets/exercise-images/kneeling-hip-flexor-1.jpg"},{"id":"standing-hamstring-calf-stretch","nameZh":"站姿腘绳肌与小腿拉伸","nameEn":"Standing Hamstring and Calf Stretch","category":"拉伸","libraryType":"stretch","level":"初级","equipment":"其他","force":"静态","mechanic":"未提供","primaryMuscles":["腘绳肌"],"secondaryMuscles":[],"instructionsZh":["将一侧脚跟放在低台或稳定支撑物上，脚尖朝上。","保持背部自然延长，从髋部轻轻前倾。","感到大腿后侧和小腿轻微牵拉时保持 20-30 秒，再换边。"],"instructionsEn":["Being by looping a belt, band, or rope around one foot. While standing, place that foot forward.","Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward.","Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot."],"startImage":"assets/exercise-images/standing-hamstring-calf-stretch-0.jpg","endImage":"assets/exercise-images/standing-hamstring-calf-stretch-1.jpg"},{"id":"wide-grip-barbell-bench-press","nameZh":"宽握杠铃卧推","nameEn":"Wide-Grip Barbell Bench Press","category":"胸部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["平躺于卧推凳，双脚稳定踩地，握距略宽于常规卧推。","肩胛后收下沉，控制杠铃下放至中下胸。","沿稳定轨迹推回，避免肘部过度外展或耸肩。"],"instructionsEn":["Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions."],"startImage":"assets/exercise-images/wide-grip-barbell-bench-press-0.jpg","endImage":"assets/exercise-images/wide-grip-barbell-bench-press-1.jpg"},{"id":"machine-bench-press","nameZh":"固定器械卧推","nameEn":"Machine Bench Press","category":"胸部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["调整座椅，让把手与中胸大致齐平。","背部贴稳靠垫，双手平稳向前推。","在不锁死肘部的前提下控制回放。"],"instructionsEn":["Sit down on the Chest Press Machine and select the weight.","Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.","Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.","Now bring the handles back towards you as you breathe in.","Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.","Repeat for the recommended amount of reps.","When finished step on the lever again and slowly get the handles back to their original place."],"startImage":"assets/exercise-images/machine-bench-press-0.jpg","endImage":"assets/exercise-images/machine-bench-press-1.jpg"},{"id":"dumbbell-neutral-grip-bench-press","nameZh":"中立握哑铃卧推","nameEn":"Dumbbell Bench Press with Neutral Grip","category":"胸部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"复合动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部","肱三头肌"],"instructionsZh":["仰卧凳上，双手持哑铃并让掌心相对。","肩胛轻微后收，控制哑铃下降至胸侧。","沿可控轨迹推起，保持手腕中立。"],"instructionsEn":["Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.","Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.","Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.","Pause, then extend the elbow and return to the starting position."],"startImage":"assets/exercise-images/dumbbell-neutral-grip-bench-press-0.jpg","endImage":"assets/exercise-images/dumbbell-neutral-grip-bench-press-1.jpg"},{"id":"chin-up","nameZh":"反握引体向上","nameEn":"Chin-Up","category":"背部","libraryType":"resistance","level":"初级","equipment":"徒手","force":"拉","mechanic":"复合动作","primaryMuscles":["背阔肌"],"secondaryMuscles":["肱二头肌","前臂","中背部"],"instructionsZh":["反握单杠，先下沉肩胛并收紧躯干。","以肘部向下带动身体，胸部向杠靠近。","控制下降至手臂接近伸直，避免摆动借力。"],"instructionsEn":["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.","As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"startImage":"assets/exercise-images/chin-up-0.jpg","endImage":"assets/exercise-images/chin-up-1.jpg"},{"id":"inverted-row","nameZh":"反向划船","nameEn":"Inverted Row","category":"背部","libraryType":"resistance","level":"初级","equipment":"未提供","force":"拉","mechanic":"复合动作","primaryMuscles":["中背部"],"secondaryMuscles":["背阔肌"],"instructionsZh":["仰卧于低杠下，身体保持从肩到脚跟的直线。","先后收肩胛，再拉动胸部靠近横杠。","控制回到起始位，避免塌腰。"],"instructionsEn":["Position a bar in a rack to about waist height. You can also use a smith machine.","Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.","Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.","Pause at the top of the motion, and return yourself to the start position.","Repeat for the desired number of repetitions."],"startImage":"assets/exercise-images/inverted-row-0.jpg","endImage":"assets/exercise-images/inverted-row-1.jpg"},{"id":"leverage-iso-row","nameZh":"固定器械独立臂划船","nameEn":"Leverage Iso Row","category":"背部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"拉","mechanic":"复合动作","primaryMuscles":["背阔肌"],"secondaryMuscles":["肱二头肌","中背部"],"instructionsZh":["调整座椅并让胸部贴稳支撑垫。","以肘部向后带动把手，顶端轻收肩胛。","缓慢回放，避免肩部向前耸起。"],"instructionsEn":["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."],"startImage":"assets/exercise-images/leverage-iso-row-0.jpg","endImage":"assets/exercise-images/leverage-iso-row-1.jpg"},{"id":"underhand-cable-pulldown","nameZh":"反握绳索下拉","nameEn":"Underhand Cable Pulldowns","category":"背部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["背阔肌"],"secondaryMuscles":["肱二头肌","中背部","肩部"],"instructionsZh":["反握高位把手，坐稳并固定大腿。","先下沉肩胛，再将把手拉向上胸。","控制上放，保持躯干稳定不后仰。"],"instructionsEn":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"startImage":"assets/exercise-images/underhand-cable-pulldown-0.jpg","endImage":"assets/exercise-images/underhand-cable-pulldown-1.jpg"},{"id":"machine-shoulder-press","nameZh":"固定器械肩推","nameEn":"Machine Shoulder (Military) Press","category":"肩部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"推","mechanic":"复合动作","primaryMuscles":["肩部"],"secondaryMuscles":["肱三头肌"],"instructionsZh":["调整座椅，让把手从肩部附近起始。","收紧腹部，平稳向上推举把手。","控制下降到舒适深度，避免耸肩或后仰。"],"instructionsEn":["Sit down on the Shoulder Press Machine and select the weight.","Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.","Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.","Lower the handles slowly back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/machine-shoulder-press-0.jpg","endImage":"assets/exercise-images/machine-shoulder-press-1.jpg"},{"id":"reverse-machine-flyes","nameZh":"反向飞鸟机","nameEn":"Reverse Machine Flyes","category":"肩部","libraryType":"resistance","level":"初级","equipment":"固定器械","force":"拉","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":[],"instructionsZh":["面向器械坐稳，胸部贴紧支撑垫。","微屈肘向两侧打开手臂，带动后三角肌。","顶端停顿后慢慢回放，避免借力甩动。"],"instructionsEn":["Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.","In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.","Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.","Pause at the rear of the movement, and slowly return the weight to the starting position."],"startImage":"assets/exercise-images/reverse-machine-flyes-0.jpg","endImage":"assets/exercise-images/reverse-machine-flyes-1.jpg"},{"id":"front-plate-raise","nameZh":"杠铃片前平举","nameEn":"Front Plate Raise","category":"肩部","libraryType":"resistance","level":"中级","equipment":"其他","force":"推","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":[],"instructionsZh":["双手托住杠铃片于大腿前，膝盖微屈站稳。","保持肘部轻微弯曲，举至接近肩高。","缓慢下降，避免身体后仰借力。"],"instructionsEn":["While standing straight, hold a barbell plate in both hands at the 3 and 9 o'clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.","Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. Tip: make sure that you do not swing the weight or bend at the elbows. Your torso should remain stationary throughout the movement as well.","As you inhale, slowly lower the plate back down to the starting position.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/front-plate-raise-0.jpg","endImage":"assets/exercise-images/front-plate-raise-1.jpg"},{"id":"one-arm-side-laterals","nameZh":"单臂哑铃侧平举","nameEn":"One-Arm Side Laterals","category":"肩部","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"推","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":[],"instructionsZh":["单手持哑铃，躯干保持稳定。","以肩部带动手臂向侧方抬起至接近肩高。","平稳下放，避免耸肩或摆动躯干。"],"instructionsEn":["Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance.","Stand with a straight torso and have the dumbbell by your side at arm's length with the palm of the hand facing you. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbell back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"startImage":"assets/exercise-images/one-arm-side-laterals-0.jpg","endImage":"assets/exercise-images/one-arm-side-laterals-1.jpg"},{"id":"band-pull-apart","nameZh":"弹力带拉开","nameEn":"Band Pull Apart","category":"肩部","libraryType":"resistance","level":"初级","equipment":"弹力带","force":"拉","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":["中背部","斜方肌"],"instructionsZh":["双手与肩同宽握住轻阻力弹力带。","保持手臂接近伸直，向两侧拉开弹力带。","肩胛后收后缓慢回到起始位。"],"instructionsEn":["Begin with your arms extended straight out in front of you, holding the band with both hands.","Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.","Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.","Pause as you complete the movement, returning to the starting position under control."],"startImage":"assets/exercise-images/band-pull-apart-0.jpg","endImage":"assets/exercise-images/band-pull-apart-1.jpg"},{"id":"incline-dumbbell-curl","nameZh":"上斜哑铃弯举","nameEn":"Incline Dumbbell Curl","category":"手臂","libraryType":"resistance","level":"初级","equipment":"哑铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":[],"instructionsZh":["坐于上斜凳，双臂自然垂于身体两侧。","固定上臂，屈肘将哑铃卷向肩部。","控制下放至肱二头肌充分拉长的位置。"],"instructionsEn":["Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/incline-dumbbell-curl-0.jpg","endImage":"assets/exercise-images/incline-dumbbell-curl-1.jpg"},{"id":"ez-bar-skullcrusher","nameZh":"曲杆仰卧臂屈伸","nameEn":"EZ-Bar Skullcrusher","category":"手臂","libraryType":"resistance","level":"初级","equipment":"曲杆","force":"推","mechanic":"孤立动作","primaryMuscles":["肱三头肌"],"secondaryMuscles":["前臂"],"instructionsZh":["仰卧凳上，双手持曲杆于胸前上方。","固定上臂，屈肘让曲杆接近额头上方。","伸肘回到起始位，避免肘部大幅外张。"],"instructionsEn":["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.","Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.","Lift the bar back to the starting position by extending the elbow and exhaling.","Repeat."],"startImage":"assets/exercise-images/ez-bar-skullcrusher-0.jpg","endImage":"assets/exercise-images/ez-bar-skullcrusher-1.jpg"},{"id":"reverse-barbell-curl","nameZh":"反握杠铃弯举","nameEn":"Reverse Barbell Curl","category":"手臂","libraryType":"resistance","level":"初级","equipment":"杠铃","force":"拉","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":["前臂"],"instructionsZh":["正握杠铃站稳，肘部靠近躯干。","固定上臂，屈肘将杠铃卷向上方。","缓慢下降，保持手腕稳定。"],"instructionsEn":["Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/reverse-barbell-curl-0.jpg","endImage":"assets/exercise-images/reverse-barbell-curl-1.jpg"},{"id":"cable-one-arm-tricep-extension","nameZh":"单臂绳索臂屈伸","nameEn":"Cable One Arm Tricep Extension","category":"手臂","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"推","mechanic":"孤立动作","primaryMuscles":["肱三头肌"],"secondaryMuscles":[],"instructionsZh":["站在滑轮旁，肘部固定于身体一侧。","伸直手肘向下或向后压动把手。","顶端收缩肱三头肌后缓慢回放。"],"instructionsEn":["With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.","Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.","As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.","Squeeze the triceps and hold for a second in this contracted position.","Slowly return the handle to the starting position.","Repeat for the recommended amount of repetitions and then perform the same movement with the other arm."],"startImage":"assets/exercise-images/cable-one-arm-tricep-extension-0.jpg","endImage":"assets/exercise-images/cable-one-arm-tricep-extension-1.jpg"},{"id":"goblet-squat","nameZh":"高脚杯深蹲","nameEn":"Goblet Squat","category":"腿部","libraryType":"resistance","level":"初级","equipment":"kettlebells","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌","肩部"],"instructionsZh":["双手将哑铃或壶铃贴近胸前，双脚站稳。","髋膝同步下屈，膝盖跟随脚尖方向。","脚掌均匀发力站起，躯干保持稳定。"],"instructionsEn":["Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.","Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.","At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."],"startImage":"assets/exercise-images/goblet-squat-0.jpg","endImage":"assets/exercise-images/goblet-squat-1.jpg"},{"id":"narrow-stance-leg-press","nameZh":"窄距腿举","nameEn":"Narrow Stance Leg Press","category":"腿部","libraryType":"resistance","level":"中级","equipment":"固定器械","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌"],"instructionsZh":["坐稳腿举机，双脚以较窄站距置于踏板中部。","控制踏板下降，腰背始终贴紧靠垫。","通过脚掌推回，避免锁死膝关节。"],"instructionsEn":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],"startImage":"assets/exercise-images/narrow-stance-leg-press-0.jpg","endImage":"assets/exercise-images/narrow-stance-leg-press-1.jpg"},{"id":"donkey-calf-raise","nameZh":"驴式提踵","nameEn":"Donkey Calf Raises","category":"腿部","libraryType":"resistance","level":"中级","equipment":"其他","force":"推","mechanic":"孤立动作","primaryMuscles":["小腿"],"secondaryMuscles":[],"instructionsZh":["前脚掌踩稳踏板或垫高处，髋部前屈并扶稳支撑物。","通过踝关节跖屈抬起脚跟至最高点。","顶端停顿后控制下降，感受小腿拉长。"],"instructionsEn":["For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.","Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/donkey-calf-raise-0.jpg","endImage":"assets/exercise-images/donkey-calf-raise-1.jpg"},{"id":"elevated-back-lunge","nameZh":"后脚抬高后撤弓步","nameEn":"Elevated Back Lunge","category":"臀部","libraryType":"resistance","level":"中级","equipment":"杠铃","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["臀肌","腘绳肌"],"instructionsZh":["前脚踩稳，后脚置于低台或稳定支撑物上。","屈髋屈膝下沉，保持骨盆稳定。","以前脚臀腿发力站起，避免前膝内扣。"],"instructionsEn":["Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.","Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.","Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.","Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating."],"startImage":"assets/exercise-images/elevated-back-lunge-0.jpg","endImage":"assets/exercise-images/elevated-back-lunge-1.jpg"},{"id":"lunge-pass-through","nameZh":"弓步穿越","nameEn":"Lunge Pass Through","category":"臀部","libraryType":"resistance","level":"中级","equipment":"kettlebells","force":"推","mechanic":"复合动作","primaryMuscles":["腘绳肌"],"secondaryMuscles":["小腿","臀肌","股四头肌"],"instructionsZh":["站稳后向后迈步进入弓步姿势。","下降时躯干稳定，让前腿臀部与大腿共同控制。","以前脚发力回到站立，再交替另一侧。"],"instructionsEn":["Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.","Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.","As you lunge, pass the kettlebell under your front leg to your opposite hand.","Pressing through the heel of your foot, return to the starting position.","Repeat the movement for the recommended amount of repetitions, alternating legs."],"startImage":"assets/exercise-images/lunge-pass-through-0.jpg","endImage":"assets/exercise-images/lunge-pass-through-1.jpg"},{"id":"kettlebell-one-legged-deadlift","nameZh":"壶铃单腿硬拉","nameEn":"Kettlebell One-Legged Deadlift","category":"臀部","libraryType":"resistance","level":"中级","equipment":"kettlebells","force":"拉","mechanic":"复合动作","primaryMuscles":["腘绳肌"],"secondaryMuscles":["臀肌","下背部"],"instructionsZh":["单脚站稳，壶铃置于支撑脚前方。","髋向后折叠，后腿向后伸展以维持平衡。","臀部发力伸髋回到站立，避免躯干旋转。"],"instructionsEn":["Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.","Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.","Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position."],"startImage":"assets/exercise-images/kettlebell-one-legged-deadlift-0.jpg","endImage":"assets/exercise-images/kettlebell-one-legged-deadlift-1.jpg"},{"id":"step-up-with-knee-raise","nameZh":"登台提膝","nameEn":"Step-up with Knee Raise","category":"臀部","libraryType":"resistance","level":"初级","equipment":"徒手","force":"推","mechanic":"复合动作","primaryMuscles":["臀肌"],"secondaryMuscles":["腘绳肌","股四头肌"],"instructionsZh":["一脚踩稳台面，另一脚自然悬空。","以台面脚臀腿发力登上台面，并抬起对侧膝盖。","控制下台，保持膝盖与脚尖方向一致。"],"instructionsEn":["Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.","Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.","Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."],"startImage":"assets/exercise-images/step-up-with-knee-raise-0.jpg","endImage":"assets/exercise-images/step-up-with-knee-raise-1.jpg"},{"id":"cable-deadlifts","nameZh":"绳索硬拉","nameEn":"Cable Deadlifts","category":"臀部","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["前臂","臀肌","腘绳肌","下背部"],"instructionsZh":["站在低位滑轮前，双手持把手并向后送髋。","保持背部中立，通过伸髋站直。","顶端收紧臀部后控制回到髋折叠位。"],"instructionsEn":["Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.","To begin, squat down be flexing your hips and knees until you can reach the handles.","After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.","After reaching a full standing position, Return to the starting position and repeat."],"startImage":"assets/exercise-images/cable-deadlifts-0.jpg","endImage":"assets/exercise-images/cable-deadlifts-1.jpg"},{"id":"bodyweight-walking-lunge","nameZh":"徒手行走弓步","nameEn":"Bodyweight Walking Lunge","category":"臀部","libraryType":"resistance","level":"初级","equipment":"未提供","force":"推","mechanic":"复合动作","primaryMuscles":["股四头肌"],"secondaryMuscles":["小腿","臀肌","腘绳肌"],"instructionsZh":["向前迈出适中步幅，双腿屈膝下沉。","前脚全掌受力，保持躯干直立稳定。","以前脚臀腿推地向前迈入下一步。"],"instructionsEn":["Begin standing with your feet shoulder width apart and your hands on your hips.","Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."],"startImage":"assets/exercise-images/bodyweight-walking-lunge-0.jpg","endImage":"assets/exercise-images/bodyweight-walking-lunge-1.jpg"},{"id":"hanging-leg-raise","nameZh":"悬垂举腿","nameEn":"Hanging Leg Raise","category":"核心","libraryType":"resistance","level":"高级","equipment":"徒手","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["双手握杠悬垂，先稳定肩胛并收紧腹部。","控制抬起双腿至舒适高度，避免摆动。","缓慢下放，在躯干稳定后开始下一次。"],"instructionsEn":["Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.","Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.","Go back slowly to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/hanging-leg-raise-0.jpg","endImage":"assets/exercise-images/hanging-leg-raise-1.jpg"},{"id":"decline-crunch","nameZh":"下斜卷腹","nameEn":"Decline Crunch","category":"核心","libraryType":"resistance","level":"中级","equipment":"徒手","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["躺于下斜凳并固定双脚，双手轻扶头侧。","收缩腹部使肩胛离开凳面。","缓慢回到起始位，避免用颈部发力。"],"instructionsEn":["Secure your legs at the end of the decline bench and lie down.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/decline-crunch-0.jpg","endImage":"assets/exercise-images/decline-crunch-1.jpg"},{"id":"knee-hip-raise-parallel-bars","nameZh":"双杠屈膝举腿","nameEn":"Knee/Hip Raise On Parallel Bars","category":"核心","libraryType":"resistance","level":"初级","equipment":"其他","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["前臂支撑于双杠，稳定肩胛和躯干。","收紧腹部，将膝盖抬向胸前。","控制下放，避免身体前后摆动。"],"instructionsEn":["Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle.","The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position.","Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to the floor and then hold the contraction for a second. Tip: Do not use any momentum or swinging as you perform this exercise.","Slowly go back to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/knee-hip-raise-parallel-bars-0.jpg","endImage":"assets/exercise-images/knee-hip-raise-parallel-bars-1.jpg"},{"id":"standing-cable-wood-chop","nameZh":"站姿绳索伐木","nameEn":"Standing Cable Wood Chop","category":"核心","libraryType":"resistance","level":"初级","equipment":"绳索器械","force":"拉","mechanic":"复合动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":["肩部"],"instructionsZh":["侧对滑轮站稳，双手握住把手。","以躯干旋转和髋部稳定带动把手斜向下拉。","控制回放，避免腰椎单独扭转。"],"instructionsEn":["Connect a standard handle to a tower, and move the cable to the highest pulley position.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.","With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.","In one motion, pull the handle down and across your body to your front knee while rotating your torso.","Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.","Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"startImage":"assets/exercise-images/standing-cable-wood-chop-0.jpg","endImage":"assets/exercise-images/standing-cable-wood-chop-1.jpg"},{"id":"weighted-sit-ups-bands","nameZh":"弹力带负重仰卧起坐","nameEn":"Weighted Sit-Ups - With Bands","category":"核心","libraryType":"resistance","level":"中级","equipment":"其他","force":"拉","mechanic":"孤立动作","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["固定弹力带后仰卧，双脚稳定踩地。","收紧腹部抬起躯干，动作不借助颈部。","控制回到起始位，保持腰部可控。"],"instructionsEn":["Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.","Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.","Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"startImage":"assets/exercise-images/weighted-sit-ups-bands-0.jpg","endImage":"assets/exercise-images/weighted-sit-ups-bands-1.jpg"},{"id":"dynamic-back-stretch","nameZh":"动态背部活动","nameEn":"Dynamic Back Stretch","category":"热身","libraryType":"warmup","level":"初级","equipment":"未提供","force":"拉","mechanic":"未提供","primaryMuscles":["背阔肌"],"secondaryMuscles":[],"instructionsZh":["站稳或跪姿准备，先让呼吸平稳。","在舒适范围内交替屈伸和旋转躯干。","动作连贯而不过度拉扯，逐步增加幅度。"],"instructionsEn":["Stand with your feet shoulder width apart. This will be your starting position.","Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head."],"startImage":"assets/exercise-images/dynamic-back-stretch-0.jpg","endImage":"assets/exercise-images/dynamic-back-stretch-1.jpg"},{"id":"dynamic-chest-stretch","nameZh":"动态胸部打开","nameEn":"Dynamic Chest Stretch","category":"热身","libraryType":"warmup","level":"初级","equipment":"未提供","force":"拉","mechanic":"未提供","primaryMuscles":["胸部"],"secondaryMuscles":["中背部"],"instructionsZh":["站稳并轻收紧腹部，双臂抬至舒适高度。","控制双臂向后打开胸前侧，再回到中立。","保持肩膀放松，动作不追求疼痛范围。"],"instructionsEn":["Stand with your hands together, arms extended directly in front of you. This will be your starting position.","Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so."],"startImage":"assets/exercise-images/dynamic-chest-stretch-0.jpg","endImage":"assets/exercise-images/dynamic-chest-stretch-1.jpg"},{"id":"elbow-circles","nameZh":"肘关节绕环","nameEn":"Elbow Circles","category":"热身","libraryType":"warmup","level":"初级","equipment":"未提供","force":"拉","mechanic":"孤立动作","primaryMuscles":["肩部"],"secondaryMuscles":["斜方肌"],"instructionsZh":["双臂抬起并轻触肩部或保持屈肘。","以肘关节带动小幅度绕圈。","完成一个方向后换方向，保持肩颈放松。"],"instructionsEn":["Sit or stand with your feet slightly apart.","Place your hands on your shoulders with your elbows at shoulder level and pointing out.","Slowly make a circle with your elbows. Breathe out as you start the circle and breathe in as you complete the circle."],"startImage":"assets/exercise-images/elbow-circles-0.jpg","endImage":"assets/exercise-images/elbow-circles-1.jpg"},{"id":"elbows-back","nameZh":"屈肘后拉","nameEn":"Elbows Back","category":"热身","libraryType":"warmup","level":"初级","equipment":"未提供","force":"静态","mechanic":"孤立动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部"],"instructionsZh":["站立并将双肘弯曲于身体两侧。","轻轻向后拉肘，感受肩胛骨靠近。","控制回到起始位，避免耸肩。"],"instructionsEn":["Stand up straight.","Place both hands on your lower back, fingers pointing downward and elbows out.","Then gently pull your elbows back aiming to touch them together."],"startImage":"assets/exercise-images/elbows-back-0.jpg","endImage":"assets/exercise-images/elbows-back-1.jpg"},{"id":"front-leg-raises","nameZh":"前摆腿","nameEn":"Front Leg Raises","category":"热身","libraryType":"warmup","level":"初级","equipment":"徒手","force":"拉","mechanic":"未提供","primaryMuscles":["腘绳肌"],"secondaryMuscles":[],"instructionsZh":["扶住稳定支撑物，单脚站稳。","让另一条腿在舒适范围内向前后摆动。","保持骨盆稳定，左右各完成后换边。"],"instructionsEn":["Stand next to a chair or other support, holding on with one hand.","Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs."],"startImage":"assets/exercise-images/front-leg-raises-0.jpg","endImage":"assets/exercise-images/front-leg-raises-1.jpg"},{"id":"groiners","nameZh":"动态髋部开合","nameEn":"Groiners","category":"热身","libraryType":"warmup","level":"中级","equipment":"徒手","force":"拉","mechanic":"复合动作","primaryMuscles":["髋内收肌群"],"secondaryMuscles":[],"instructionsZh":["从俯撑或弓步准备姿势开始，双手稳定支撑。","交替将一侧脚迈至同侧手外侧。","保持脊柱自然延长，左右流畅交替。"],"instructionsEn":["Begin in a pushup position on the floor. This will be your starting position.","Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.","Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions."],"startImage":"assets/exercise-images/groiners-0.jpg","endImage":"assets/exercise-images/groiners-1.jpg"},{"id":"hip-circles-prone","nameZh":"俯卧髋绕环","nameEn":"Hip Circles (prone)","category":"热身","libraryType":"warmup","level":"初级","equipment":"徒手","force":"拉","mechanic":"孤立动作","primaryMuscles":["髋外展肌群"],"secondaryMuscles":["髋内收肌群"],"instructionsZh":["俯卧并保持骨盆稳定，单腿屈膝抬起。","以髋关节带动膝盖缓慢画圈。","完成一侧后换边，动作范围以舒适为准。"],"instructionsEn":["Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.","Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.","Perform this slowly for a number of repetitions, and repeat on the other side."],"startImage":"assets/exercise-images/hip-circles-prone-0.jpg","endImage":"assets/exercise-images/hip-circles-prone-1.jpg"},{"id":"inchworm","nameZh":"尺蠖爬行","nameEn":"Inchworm","category":"热身","libraryType":"warmup","level":"初级","equipment":"徒手","force":"未提供","mechanic":"复合动作","primaryMuscles":["腘绳肌"],"secondaryMuscles":[],"instructionsZh":["站立后从髋部前屈，双手走向俯撑位。","保持腹部轻收紧，手脚交替小步移动。","在可控范围内回到站立，不强行拉伸腘绳肌。"],"instructionsEn":["Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position.","Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.","Keep going until your body is parallel to the ground in a pushup position.","Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.","Continue walking until your feet are by hour hands, keeping your legs straight as you do so."],"startImage":"assets/exercise-images/inchworm-0.jpg","endImage":"assets/exercise-images/inchworm-1.jpg"},{"id":"shoulder-circles","nameZh":"肩关节绕环","nameEn":"Shoulder Circles","category":"热身","libraryType":"warmup","level":"初级","equipment":"未提供","force":"拉","mechanic":"未提供","primaryMuscles":["肩部"],"secondaryMuscles":["斜方肌"],"instructionsZh":["站稳，双臂自然垂于身体两侧。","双肩向前、向上、向后做缓慢绕环。","完成一个方向后换方向，保持颈部放松。"],"instructionsEn":["With shoulders relaxed and arms resting loosely at your sides (or in your lap if you're seated), gently roll your shoulders forward, up, back, and down.","Reverse direction. You can do this exercise alternating shoulders or both at the same time."],"startImage":"assets/exercise-images/shoulder-circles-0.jpg","endImage":"assets/exercise-images/shoulder-circles-1.jpg"},{"id":"torso-rotation","nameZh":"躯干旋转","nameEn":"Torso Rotation","category":"热身","libraryType":"warmup","level":"初级","equipment":"健身球","force":"拉","mechanic":"未提供","primaryMuscles":["腹部肌群"],"secondaryMuscles":[],"instructionsZh":["双脚与髋同宽站立，膝盖微屈。","保持骨盆大致稳定，舒适地左右旋转胸椎。","动作平稳，不用腰椎猛甩。"],"instructionsEn":["Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position.","Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions."],"startImage":"assets/exercise-images/torso-rotation-0.jpg","endImage":"assets/exercise-images/torso-rotation-1.jpg"},{"id":"worlds-greatest-stretch","nameZh":"世界最佳拉伸","nameEn":"World's Greatest Stretch","category":"热身","libraryType":"warmup","level":"中级","equipment":"未提供","force":"静态","mechanic":"未提供","primaryMuscles":["腘绳肌"],"secondaryMuscles":["小腿","臀肌","股四头肌"],"instructionsZh":["从弓步开始，同侧手靠近前脚内侧。","向上打开胸口和手臂，再回到弓步。","左右交替完成，动作缓慢可控。"],"instructionsEn":["This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds.","Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the stretch.","After 10-20 seconds, place your hands on either side of your front foot. Raise the toes of the front foot off of the ground, and straighten your leg. You may need to reposition your rear leg to do so. Hold for 10-20 seconds, and then repeat the entire sequence for the other side."],"startImage":"assets/exercise-images/worlds-greatest-stretch-0.jpg","endImage":"assets/exercise-images/worlds-greatest-stretch-1.jpg"},{"id":"behind-head-chest-stretch","nameZh":"抱头胸部拉伸","nameEn":"Behind Head Chest Stretch","category":"拉伸","libraryType":"stretch","level":"高级","equipment":"其他","force":"静态","mechanic":"孤立动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部"],"instructionsZh":["站立或坐姿保持脊柱自然延长，双手轻放头后。","轻轻打开肘部，感受胸前侧拉伸。","保持自然呼吸，拉伸感应温和无痛。"],"instructionsEn":["Sit upright on the floor with your partner behind you.","Place your hands behind your hand, and push your elbows back as far as you can. Your partner should hold your elbows. This will be your starting position.","Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds. Your partner should prevent your elbows from moving.","Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury."],"startImage":"assets/exercise-images/behind-head-chest-stretch-0.jpg","endImage":"assets/exercise-images/behind-head-chest-stretch-1.jpg"},{"id":"calf-stretch-hands-wall","nameZh":"扶墙小腿拉伸","nameEn":"Calf Stretch Hands Against Wall","category":"拉伸","libraryType":"stretch","level":"初级","equipment":"未提供","force":"静态","mechanic":"孤立动作","primaryMuscles":["小腿"],"secondaryMuscles":[],"instructionsZh":["双手扶墙，一腿向后伸直并让脚跟贴地。","身体缓慢前移，感受后侧小腿牵拉。","保持 20-30 秒后换边，避免弹震。"],"instructionsEn":["Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.","Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.","Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides."],"startImage":"assets/exercise-images/calf-stretch-hands-wall-0.jpg","endImage":"assets/exercise-images/calf-stretch-hands-wall-1.jpg"},{"id":"childs-pose","nameZh":"婴儿式拉伸","nameEn":"Child's Pose","category":"拉伸","libraryType":"stretch","level":"初级","equipment":"未提供","force":"静态","mechanic":"未提供","primaryMuscles":["下背部"],"secondaryMuscles":["臀肌","中背部"],"instructionsZh":["跪姿后将臀部向脚跟方向坐回。","双臂向前延展，额头可轻触地面或垫面。","在背部和肩部有轻微牵拉时自然呼吸。"],"instructionsEn":["Get on your hands and knees, walk your hands in front of you.","Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.","Once you settle onto your heels, bring your hands next to your feet and relax. \"breathe\" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems."],"startImage":"assets/exercise-images/childs-pose-0.jpg","endImage":"assets/exercise-images/childs-pose-1.jpg"},{"id":"chest-front-shoulder-stretch","nameZh":"胸前与肩前侧拉伸","nameEn":"Chest And Front Of Shoulder Stretch","category":"拉伸","libraryType":"stretch","level":"初级","equipment":"其他","force":"静态","mechanic":"孤立动作","primaryMuscles":["胸部"],"secondaryMuscles":["肩部"],"instructionsZh":["一手扶住稳定支撑物，手臂略低于肩高。","身体缓慢转离支撑手，感受胸前与肩前侧牵拉。","保持无痛范围，换侧重复。"],"instructionsEn":["Start off by standing with your legs together, holding a bodybar or a broomstick.","Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down.","Carefully lift the pole up and behind your head."],"startImage":"assets/exercise-images/chest-front-shoulder-stretch-0.jpg","endImage":"assets/exercise-images/chest-front-shoulder-stretch-1.jpg"},{"id":"lying-glute-stretch","nameZh":"仰卧臀肌拉伸","nameEn":"Lying Glute","category":"拉伸","libraryType":"stretch","level":"高级","equipment":"徒手","force":"静态","mechanic":"未提供","primaryMuscles":["臀肌"],"secondaryMuscles":["髋外展肌群"],"instructionsZh":["仰卧后将一侧脚踝搭在另一侧大腿上。","双手轻轻将支撑腿向身体拉近。","感受臀部外侧轻微牵拉，保持后换边。"],"instructionsEn":["Lie on your back with your partner kneeling beside you.","Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position.","Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.","After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching."],"startImage":"assets/exercise-images/lying-glute-stretch-0.jpg","endImage":"assets/exercise-images/lying-glute-stretch-1.jpg"},{"id":"overhead-lat-stretch","nameZh":"过头背阔肌拉伸","nameEn":"Overhead Lat","category":"拉伸","libraryType":"stretch","level":"高级","equipment":"其他","force":"静态","mechanic":"未提供","primaryMuscles":["背阔肌"],"secondaryMuscles":["肱三头肌"],"instructionsZh":["站立或跪姿，将一侧手臂举过头顶。","身体轻轻向对侧侧屈，保持肩部放松。","感受腋下至背侧拉伸后换边。"],"instructionsEn":["Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position.","Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch sides."],"startImage":"assets/exercise-images/overhead-lat-stretch-0.jpg","endImage":"assets/exercise-images/overhead-lat-stretch-1.jpg"},{"id":"seated-hamstring-stretch","nameZh":"坐姿腘绳肌拉伸","nameEn":"Seated Hamstring","category":"拉伸","libraryType":"stretch","level":"高级","equipment":"未提供","force":"静态","mechanic":"未提供","primaryMuscles":["腘绳肌"],"secondaryMuscles":["小腿"],"instructionsZh":["坐姿伸直一侧腿，另一侧腿舒适弯曲。","从髋部轻轻前倾，保持背部自然延长。","感受大腿后侧牵拉，避免强行压低身体。"],"instructionsEn":["In a seated position with your legs extended, have your partner stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."],"startImage":"assets/exercise-images/seated-hamstring-stretch-0.jpg","endImage":"assets/exercise-images/seated-hamstring-stretch-1.jpg"},{"id":"standing-soleus-achilles-stretch","nameZh":"站姿比目鱼肌与跟腱拉伸","nameEn":"Standing Soleus And Achilles Stretch","category":"拉伸","libraryType":"stretch","level":"初级","equipment":"未提供","force":"静态","mechanic":"孤立动作","primaryMuscles":["小腿"],"secondaryMuscles":[],"instructionsZh":["双手扶墙，后脚脚跟持续贴地。","轻微弯曲后腿膝盖并缓慢前移身体。","感受小腿深层与跟腱牵拉后换边。"],"instructionsEn":["Stand with your feet hip-distance apart, one foot slightly in front of the other.","Bend both knees, keeping your back heel on the floor. Switch sides."],"startImage":"assets/exercise-images/standing-soleus-achilles-stretch-0.jpg","endImage":"assets/exercise-images/standing-soleus-achilles-stretch-1.jpg"},{"id":"standing-biceps-stretch","nameZh":"站姿肱二头肌拉伸","nameEn":"Standing Biceps Stretch","category":"拉伸","libraryType":"stretch","level":"初级","equipment":"其他","force":"静态","mechanic":"孤立动作","primaryMuscles":["肱二头肌"],"secondaryMuscles":["胸部","肩部"],"instructionsZh":["一侧手臂向后伸并轻扶稳定支撑物。","手心尽量向外，身体缓慢转离手臂。","感受上臂前侧拉伸，保持无痛后换边。"],"instructionsEn":["Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward.","Raise your arms up and hold until you feel a stretch in your biceps."],"startImage":"assets/exercise-images/standing-biceps-stretch-0.jpg","endImage":"assets/exercise-images/standing-biceps-stretch-1.jpg"},{"id":"spinal-stretch","nameZh":"脊柱放松拉伸","nameEn":"Spinal Stretch","category":"拉伸","libraryType":"stretch","level":"初级","equipment":"未提供","force":"静态","mechanic":"孤立动作","primaryMuscles":["中背部"],"secondaryMuscles":["背阔肌","下背部","neck","斜方肌"],"instructionsZh":["坐姿或跪姿保持呼吸平稳。","在舒适范围内轻轻屈曲并延展脊柱。","避免憋气和强行压到末端范围。"],"instructionsEn":["Sit in a chair so your back is straight and your feet planted on the floor.","Interlace your fingers behind your head, elbows out and your chin down.","Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.","Return to upright position and then repeat for your other side."],"startImage":"assets/exercise-images/spinal-stretch-0.jpg","endImage":"assets/exercise-images/spinal-stretch-1.jpg"},{"id":"tricep-side-stretch","nameZh":"肱三头肌侧向拉伸","nameEn":"Tricep Side Stretch","category":"拉伸","libraryType":"stretch","level":"初级","equipment":"未提供","force":"静态","mechanic":"未提供","primaryMuscles":["肱三头肌"],"secondaryMuscles":["肩部"],"instructionsZh":["一侧手臂举过头顶并屈肘。","另一手轻扶肘部，身体轻微向对侧侧屈。","感受上臂后侧与侧腰牵拉后换边。"],"instructionsEn":["Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep. Then repeat for your other arm."],"startImage":"assets/exercise-images/tricep-side-stretch-0.jpg","endImage":"assets/exercise-images/tricep-side-stretch-1.jpg"}];
